TN.defSec("pediatrics",{"pediatric-fever-sbi":{"id":"pediatric-fever-sbi","variants":[{"id":"fever-neonate","o":{"I":[{"t":"Chest x-ray if respiratory signs (cough, tachypnea or hypoxemia) are present; optional if no respiratory symptoms"}],"L":[{"t":"CBC, blood culture, urinalysis and urine culture, lumbar puncture for CSF cell count, Gram stain and culture; stool studies if diarrhea"}],"A":[{"t":"Ampicillin 50 mg/kg IV (Listeria monocytogenes) plus either Gentamicin 2.5 mg/kg IV or Cefotaxime 50 mg/kg IV","fl":[{"k":"ci","v":"avoid ceftriaxone in this age group"}]}],"Co":[{"t":"Admit"}]},"name":"Febrile neonate 0–28 days","level":"I","imp":"Fever in neonate 0–28 days (rule out serious bacterial illness)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"نوزاد ۱۴ روزه با تب 38.3 و تغذیه ضعیف.","why":"نوزاد: بیشترین خطر؛ ارزیابی کامل، آنتی‌بیوتیک تجربی و بستری برای همه."},{"id":"fever-infant-29-90d","o":{"I":[{"t":"Chest radiograph for infants with a suggestion of lower respiratory tract disease"}],"L":[{"t":"CBC (WBC 5000 to 15,000/mm3 for Rochester and Philadelphia, 5000 to 20,000/mm3 for Boston), blood culture, urinalysis and urine culture (catheterization or suprapubic tap), CSF cell count, glucose, protein, Gram stain and culture (lumbar puncture); CRP or procalcitonin may support differentiating SBI from viral illness"}],"A":[{"t":"Ceftriaxone 50 mg/kg IM/IV pending cultures (inpatient or outpatient, or no antibiotics with close follow-up in 12 to 24 hours); cultures of CSF, urine and blood before antibiotics","if":"low risk"},{"t":"Parenteral ceftriaxone 50 mg/kg (100 mg/kg with signs of meningitis)","if":"ill-appearing or fails low-risk criteria"}],"Co":[{"t":"Admit if ill-appearing or not low-risk; low-risk infants managed with follow-up typically within 12 to 24 hours"}]},"name":"Febrile infant 29–90 days","level":"II","imp":"Fever in infant 29–90 days","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"شیرخوار ۶۰ روزه با تب 38.6، ظاهر خوب و بدون کانون.","why":"Rochester/Boston/Philadelphia برای طبقه‌بندی؛ UA و CBC؛ LP در معیارهای Boston/Philadelphia."},{"id":"fever-infant-3-36m","o":{"L":[{"t":"Urinalysis and urine culture (by catheterization or suprapubic tap) if no other source of fever is identified (girls 6–24 months, boys 6–12 months, uncircumcised boys 12–24 months); consider CBC and blood culture, and CSF studies, much less commonly"}],"A":[{"t":"Cefixime 8 mg/kg/dose daily, or Cefpodoxime 5 mg/kg/dose twice a day, or Cefdinir 7 mg/kg/dose twice daily for 10 days as outpatient","if":"UTI"},{"t":"consider Ceftriaxone 50 mg/kg IV/IM and follow-up in 24 hours","if":"WBC ≥ 15,000/mm3 in 57 days to 6 months with T ≥ 39°C"}],"T":[{"t":"Remove excessive clothing and blankets"},{"t":"Acetaminophen 15 mg/kg PO/PR every 4 hours (up to 5 times a day)"},{"t":"Ibuprofen 10 mg/kg PO in children older than 1 year, repeat every 6 to 8 hours (maximum 40 mg/kg in 24 hours), can be given concurrently with acetaminophen"}],"Co":[{"t":"Discharge if negative; counsel parents against fever phobia"}]},"name":"Febrile infant/child 3–36 months, no source","level":"III","imp":"Fever without source in a child 3–36 months","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"دختر ۱۰ ماهه با تب 39.5 بدون کانون واضح.","why":"عمدتاً ویروسی؛ UA و کشت ادرار برای رد UTI (دختران قبل از toilet training)."},{"id":"fever-child-older","o":{"L":[{"t":"Testing directed by clinical presentation (viral infection, streptococcal pharyngitis, pneumonia, sinusitis); CBC and blood cultures not routinely recommended in immunized older children"}],"T":[{"t":"Acetaminophen 15 mg/kg PO/PR every 4 hours, or Ibuprofen 10 mg/kg PO every 6 hours as needed"}]},"name":"Febrile child older than 36 months","level":"III","imp":"Fever in child older than 36 months","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"پسر ۵ ساله با تب 39 و گلودرد.","why":"خطر باکتریمی < 0.2٪؛ آزمایش بر اساس بالین؛ تب‌بر."}],"ch":"66","name":"Fever and serious bacterial illness (SBI) in children by age group","name_fa":"تب و بیماری باکتریال جدی (SBI) در کودکان بر اساس سن","cc":["pediatric-fever","fever"],"keywords":"febrile infant, neonatal fever, serious bacterial illness, Rochester criteria, Philadelphia protocol, Boston criteria, lumbar puncture, ampicillin, gentamicin, cefotaxime, ceftriaxone, acetaminophen, ibuprofen, تب نوزاد","status":"draft","features":["شایع‌ترین شکایت اطفال در ED و 30٪ ویزیت‌های سرپایی؛ SBI شامل UTI، پنومونی، باکتریمی/سپسیس و مننژیت (به ترتیب شیوع)","نوزاد بیشترین خطر؛ شیرخوار 1 تا 3 ماه به‌تدریج خطر کمتر؛ UTI حدود 5٪ در 2 ماه تا 2 سال و 3٪ تا 8٪ در کودکان تب‌دار ED؛ باکتریمی مخفی 3 تا 36 ماه 0.5٪ تا 0.7٪؛ مننژیت از 1٪ ماه اول به < 0.1٪","آستانه تب: < 3 ماه: 38°C؛ 3 تا 36 ماه: 39°C","ممکن است تنها علامت: گریه مداوم، تسکین‌ناپذیری، تغذیه ضعیف یا بی‌ثباتی دما؛ در نوزاد حتی فقط تب","شیرخوار < 3 ماه: شرح حال و معاینه به ندرت کمک می‌کند؛ مننژیسم نادر؛ رال ممکن است شنیده نشود؛ باکتریمی حتی در خوش‌حال","شیرخوار ظاهر بدحال: ارزیابی کامل سپسیس، آنتی‌بیوتیک تزریقی و بستری","29 تا 90 روز: طبقه‌بندی خطر کم/زیاد با Rochester، Boston یا Philadelphia (ظاهر خوب، UA و WBC طبیعی 5000 تا 15000 در Rochester/Philadelphia و تا 20000 در Boston؛ CSF منفی)","3 تا 36 ماه: معاینه قابل‌اعتمادتر؛ بیشتر ویروسی؛ UTI مخفی: دختران قبل از toilet training، پسران ختنه‌شده < 6 ماه و ختنه‌نشده < 1 سال","بزرگ‌تر از 3 سال: باکتریمی < 0.2٪؛ CBC و کشت خون روتین نیست؛ ویروسی، استرپتوکوک حلق، پنومونی و سینوزیت"],"ddx":[{"n":"Sepsis / bacteremia |","cm":1},{"n":"Meningitis |","cm":1},{"n":"Urinary tract infection |"},{"n":"Pneumonia |"},{"n":"Viral illness (RSV, influenza) |"},{"n":"Streptococcal pharyngitis / sinusitis / otitis media |"}],"redflags":["ظاهر سمی، هیپوترمی، تاکی‌کاردی پایدار، کاهش پرفیوژن، تغییر هوشیاری"],"guide":"# 0 تا 28 روز\nهمه تب‌دارها: ارزیابی کامل SBI، بستری و آنتی‌بیوتیک تجربی: ampicillin 50 mg/kg IV (Listeria) و gentamicin 2.5 mg/kg IV یا cefotaxime 50 mg/kg IV؛ ceftriaxone در این سن پرهیز. آزمایش: CBC، کشت خون، UA و کشت ادرار، LP (CSF و کشت)؛ CXR اگر علائم تنفسی؛ کشت مدفوع در اسهال. اگر ظاهر بدحال SBI 13% تا 21%؛ ظاهر خوب < 5%.\n# 29 تا 90 روز\nکم‌خطر: ceftriaxone 50 mg/kg IM/IV تا نتیجه کشت (بستری)، یا بدون آنتی‌بیوتیک، یا سرپایی با ceftriaxone؛ پیگیری 12 تا 24 ساعت؛ قبل از آنتی‌بیوتیک CSF، ادرار و خون کشت. ظاهر بدحال: آنتی‌بیوتیک تزریقی و بستری. ویروسی شناخته‌شده (RSV، انفلوانزا): UTI و باکتریمی را رد کن؛ CXR اختیاری؛ LP قابل تعویق.\n# 57 روز تا 6 ماه\n≥ 38: UA و کشت ادرار؛ منفی: ترخیص؛ UTI: cefixime 8 mg/kg/dose روزانه یا cefpodoxime 5 mg/kg/dose دو بار روزانه یا cefdinir 7 mg/kg/dose دو بار روزانه 10 روز؛ شکست معیارها: ceftriaxone تزریقی و بستری. ≥ 39: UA و کشت ± CBC و کشت خون؛ WBC ≥ 15000: ceftriaxone 50 mg/kg IV/IM و پیگیری 24 ساعت؛ WBC ≥ 20000: CXR و CSF.\n# 6 تا 36 ماه\nUA و کشت در دختران 6–24 ماه، پسران 6–12 ماه، پسران ختنه‌نشده 12–24 ماه؛ منفی: ترخیص.\n# تب‌بر\nلباس اضافه را بردار؛ acetaminophen 15 mg/kg PO/PR هر 4 ساعت (تا 5 بار در روز)؛ ibuprofen 10 mg/kg PO بالای 1 سال هر 6 تا 8 ساعت (حداکثر 40 mg/kg در 24 ساعت). والدین را از «فیور فوبیا» برحذر کن.","pearls":["ceftriaxone در نوزاد ≤ 28 روز ممنوع.","بیمار با کشت خون مثبت: بستری و آنتی‌بیوتیک تزریقی؛ اگر هنوز تب‌دار یا بدحال: ارزیابی کامل سپسیس."],"section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 66: Fever and Serious Bacterial Illness in Children, pp. 353–360"},"pediatric-sepsis":{"id":"pediatric-sepsis","variants":[{"id":"sepsis-peds-shock","o":{"L":[{"t":"CBC, blood culture, complete metabolic panel, blood lactate, glucose (always), catheterized urinalysis with culture and sensitivities, lumbar puncture, stool studies if diarrhea"}],"S":[{"t":"20 mL/kg boluses of 0.9% normal saline (preferably 60 mL/kg within 15 minutes; for infants push actual volumes using multiple saline flushes); repeat until vital signs, perfusion, mental status and urine output improve, up to 100 mL/kg total","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]},{"t":"5 mL/kg 10% dextrose","if":"hypoglycemia"}],"A":[{"t":"Cefotaxime 50 mg/kg IV, or Piperacillin-tazobactam 100 mg/kg IV; add Vancomycin 15 mg/kg IV for ill-appearing infants (ceftriaxone-resistant S. pneumoniae); do not delay antibiotics for lumbar puncture"}],"T":[{"t":"Volume-refractory shock: Dopamine 5 to 20 μg/kg/min or Norepinephrine 0.1 to 0.2 μg/kg/min"},{"t":"Endotracheal intubation in respiratory failure or severe respiratory distress; secure IV or IO access"}],"Co":[{"t":"PICU; consider drug-resistant organisms, immune-incompetence or unusual organisms"}]},"name":"Pediatric septic shock","level":"I","imp":"Septic shock in a child","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"portable","o2":"O2 therapy: high-flow oxygen immediately; intubate in respiratory failure or severe respiratory distress","sc":"شیرخوار ۶ ماهه با تب، بی‌حالی، پرشدن مویرگی ۵ ثانیه و تاکی‌کاردی 190.","why":"شوک سپتیک کودک: بولوس 20 mL/kg، آنتی‌بیوتیک فوری و وازوپرسور."}],"ch":"66","name":"Pediatric sepsis and septic shock","name_fa":"سپسیس و شوک سپتیک کودکان","cc":["pediatric-fever","hypotension-shock"],"keywords":"pediatric sepsis, septic shock, 20 mL/kg bolus, dopamine, norepinephrine, vancomycin, cefotaxime, piperacillin-tazobactam, سپسیس کودک","status":"draft","features":["باکتریمی همراه شواهد بالینی عفونت سیستمیک؛ پیشرفت سریع به نارسایی چندارگانی؛ عوامل خطر: نارس بودن، نقص ایمنی، پروسیجر تهاجمی اخیر، کاتتر یا جسم خارجی دائم","شیرخوار: علائم مبهم (بی‌حالی، تغذیه ضعیف، تحریک‌پذیری، هیپوتونی)؛ تب شایع؛ شیرخوار خیلی کوچک ممکن است هیپوترم باشد","تاکی‌پنه و تاکی‌کاردی؛ شوک: پرشدن مویرگی طولانی، نبض ضعیف، تغییر هوشیاری، کاهش ادرار؛ هیپوتانسیون علامت دیررس؛ تاکی‌کاردی پایدار نسبت به سن اغلب تنها نشانه","تشخیص بالینی و تأیید با کشت خون؛ هر شیرخوار سمی را سپتیک بدان؛ خطر هیپوگلیسمی: قند همیشه چک شود"],"ddx":[{"n":"Septic shock |","cm":1},{"n":"Meningitis |","cm":1},{"n":"Hypoglycemia / metabolic emergency |"},{"n":"Pneumonia / UTI |"},{"n":"Cardiogenic shock / anaphylaxis |"}],"redflags":["پرشدن مویرگی طولانی، تغییر هوشیاری، هیپوتانسیون (دیررس)، هیپوگلیسمی"],"guide":"ABC: اکسیژن با جریان بالا، مانیتور قلبی، IV یا IO فوری؛ اینتوباسیون در نارسایی تنفسی یا دیسترس شدید. شوک: بولوس 20 mL/kg نرمال سالین 0.9٪؛ ترجیحاً 60 mL/kg در 15 دقیقه؛ در شیرخوار حجم واقعی را با فلاش‌های متعدد تزریق کن؛ تکرار تا بهبود علائم حیاتی، پرفیوژن، هوشیاری و ادرار تا کل 100 mL/kg. هیپوگلیسمی: 5 mL/kg دکستروز 10٪. آنتی‌بیوتیک فوری بلافاصله پس از IV، بدون تأخیر برای LP: cefotaxime 50 mg/kg IV یا piperacillin-tazobactam 100 mg/kg IV؛ برای شیرخوار بدحال به دلیل S. pneumoniae مقاوم به ceftriaxone vancomycin 15 mg/kg IV اضافه شود. شوک مقاوم به حجم: dopamine 5 تا 20 μg/kg/min یا norepinephrine 0.1 تا 0.2 μg/kg/min. ارگانیسم مقاوم، نقص ایمنی یا ارگانیسم نامعمول را در نظر بگیر.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 66: Fever and Serious Bacterial Illness in Children, pp. 353–360"},"pediatric-meningitis":{"id":"pediatric-meningitis","variants":[{"id":"meningitis-peds","o":{"I":[{"t":"Cranial CT before lumbar puncture only if focal neurologic signs or increased intracranial pressure"}],"L":[{"t":"Lumbar puncture: CSF white blood cells, glucose and protein, Gram stain, culture; HSV PCR in the seizing neonate and any child with CSF pleocytosis or xanthochromia; blood and urine cultures"}],"A":[{"t":"Empiric antibiotic by age: neonate 0–28 days: Ampicillin 50 mg/kg and either Cefotaxime 50 mg/kg or Gentamicin 2.5 mg/kg; 29–56 days: Ceftriaxone 50 mg/kg (100 mg/kg with signs of meningitis)","fl":[{"k":"note","v":"dosing for older children per Table 66-4 of the chapter"}]},{"t":"Acyclovir 20 mg/kg IV for any suspicion of herpes encephalitis"}],"T":[{"t":"ABCs and restoration of oxygenation and perfusion (see sepsis); do not defer antibiotics when meningitis is strongly suspected"},{"t":"Steroids: role highly controversial; possible benefit only if given prior to antibiotics"},{"t":"If lumbar puncture fails: admit, hydrate, give meningitis doses of antibiotic and obtain blood and urine cultures"}],"Co":[{"t":"Admit"}]},"name":"Suspected meningitis in infant or child","level":"I","imp":"Suspected bacterial meningitis in a child","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"شیرخوار ۸ ماهه با تب، تحریک‌پذیری، تسکین‌ناپذیری و تشنج.","why":"مننژیت: آنتی‌بیوتیک بدون تأخیر؛ LP برای تأیید؛ CT قبل از LP فقط در علائم کانونی."}],"ch":"66","name":"Pediatric meningitis","name_fa":"مننژیت کودکان","cc":["pediatric-fever","headache","altered-mental-status"],"keywords":"meningitis, lumbar puncture, CSF, acyclovir, HSV encephalitis, dexamethasone, vancomycin, ceftriaxone, مننژیت","status":"draft","features":["معمولاً عارضه باکتریمی اولیه؛ اوج بروز بین تولد تا 2 سال؛ نارسی و نقص ایمنی خطر بیشتر","ممکن است با علائم ظریف مثل اوتیت یا سینوزیت شروع شود؛ شیرخوار: تحریک‌پذیری، تسکین‌ناپذیری، هیپوتونی و بی‌حالی؛ بزرگ‌تر: سردرد، ترس از نور، تهوع/استفراغ، مننژیسم و گردن‌درد","گاهی فولمینانت: شوک، تشنج، کما یا استاتوس تب‌دار","تشخیص: LP و CSF: WBC، گلوکز و پروتئین، Gram و کشت؛ HSV PCR در نوزاد تشنجی و هر کودک با پلئوسیتوز یا xanthochromia؛ CT سر قبل از LP در علائم کانونی یا افزایش ICP؛ ایمنوساپرس: ارگانیسم‌های فرصت‌طلب","مننژیسم در < 6 ماه (به‌ویژه < 2 ماه) دشوار قابل تشخیص است؛ LP روتین < 2 ماه"],"ddx":[{"n":"Bacterial meningitis |","cm":1},{"n":"HSV encephalitis |","cm":1},{"n":"Sepsis |"},{"n":"Febrile seizure / viral meningitis |"},{"n":"Intracranial mass / hemorrhage |"}],"redflags":["تشنج، کما، شوک، علائم عصبی کانونی"],"guide":"ابتدا ABC و اصلاح اکسیژناسیون و پرفیوژن (مثل سپسیس). آنتی‌بیوتیک بر اساس سن (جدول 66-4): نوزاد: ampicillin 50 mg/kg + cefotaxime 50 mg/kg یا gentamicin 2.5 mg/kg؛ 29–56 روز: ceftriaxone 50 mg/kg با CSF طبیعی و 100 mg/kg با علائم مننژیت. شک قوی: آنتی‌بیوتیک را به تأخیر نینداز. acyclovir 20 mg/kg IV در شک به آنسفالیت هرپسی. نقش استروئید جنجالی؛ فقط اگر قبل از آنتی‌بیوتیک. اگر LP ناموفق: بستری، هیدراتاسیون، آنتی‌بیوتیک با دوز مننژیت، کشت خون و ادرار؛ LP بعد از هیدراتاسیون ممکن است موفق شود.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 66: Fever and Serious Bacterial Illness in Children, pp. 353–360"},"neonatal-feeding-gi":{"id":"neonatal-feeding-gi","variants":[{"id":"neonate-gi-benign","o":{"T":[{"t":"Parental reassurance if weight gain is adequate and the infant appears satisfied after feeding","fl":[{"k":"note","v":"no orders required"}]}]},"name":"Neonatal regurgitation / normal stool / abdominal distention, thriving","level":"III","imp":"Neonatal feeding or stooling concern (benign)","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"نوزاد ۱۰ روزه با برگشت شیر بعد از تغذیه؛ وزن‌گیری خوب.","why":"regurgitation در نوزاد با رشد کافی: اطمینان‌بخشی."},{"id":"neonate-gi-surgical","o":{"I":[{"t":"Upper gastrointestinal series with small bowel follow through (bilious vomiting); ultrasound (pyloric stenosis); abdominal radiography (pneumatosis intestinalis or free air in necrotizing enterocolitis)"}],"L":[{"t":"Sepsis evaluation if NEC suspected (jaundice, lethargy, fever, poor feeding, abdominal distention)","fl":[{"k":"note","v":"components per Chapter 66"}]}],"S":[{"t":"Parenteral rehydration for dehydrated neonates","fl":[{"k":"note","v":"volume not given in the book"}]}],"Co":[{"t":"Emergent pediatric surgical consultation; admission"}]},"name":"Bilious vomiting / suspected surgical abdomen / NEC","level":"I","imp":"Neonatal surgical abdominal emergency (malrotation with volvulus / NEC / pyloric stenosis / incarcerated hernia)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"portable","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"نوزاد ۵ روزه با استفراغ سبز، اتساع شکم و بی‌حالی.","why":"استفراغ صفراوی = اورژانس جراحی تا خلاف آن ثابت شود؛ بررسی تصویری و مشاوره فوری."}],"ch":"67","name":"Neonatal feeding, vomiting, stooling and abdominal catastrophes","name_fa":"مشکلات تغذیه، استفراغ، مدفوع و اورژانس‌های شکمی نوزاد","cc":["pediatric-gi","pediatric-other"],"keywords":"neonate, regurgitation, bilious vomiting, malrotation, midgut volvulus, pyloric stenosis, necrotizing enterocolitis, Hirschsprung, inguinal hernia, bloody stool, استفراغ صفراوی نوزاد","status":"draft","features":["تغذیه: شیشه 6 تا 9 وعده (2 تا 4 oz)؛ شیر مادر هر 1 تا 3 ساعت؛ کاهش تا 12٪ وزن تولد در 3 تا 7 روز اول؛ سپس حدود 20 تا 30 g/d تا 3 ماهگی","regurgitation: خروج بدون زحمت محتویات معده تا 30 دقیقه بعد، هرگز پرتابی یا صفراوی؛ خودمحدود؛ در نوزاد با رشد خوب اطمینان‌بخشی","استفراغ: انقباض دیافراگم و عضلات شکم؛ علل: افزایش ICP (NAT)، عفونت (UTI، سپسیس، گاستروانتریت)، بیماری هپاتوبیلیاری (با ایکتر)، IEM (با هیپوگلیسمی و اسیدوز)","استفراغ صفراوی: اورژانس جراحی؛ malrotation با volvulus","مدفوع: شیرخوار شیری ممکن است 5 تا 7 روز مدفوع نکند؛ رنگ بی‌اهمیت مگر خون یا آکولیک (سفید)","بدون مدفوع در 2 روز اول: آترزی/تنگی، CF، Hirschsprung، مکونیوم پلاگ؛ یبوست بعدی: Hirschsprung، کم‌کاری تیروئید، تنگی مقعد","خون در مدفوع: شایع‌ترین علت شقاق مقعد؛ خون بلعیده مادر؛ NEC (سپسیس، ایکتر، بی‌حالی، تب، تغذیه ضعیف، اتساع؛ رادیوگرافی: pneumatosis یا هوای آزاد)","اتساع شکم می‌تواند طبیعی باشد (عضلات شل، اندام‌های نسبتاً بزرگ، هوای بلعیده)؛ راحت، تغذیه خوب و شکم نرم: نگرانی نیست","فاجعه شکمی: تحریک‌پذیری، تغذیه ضعیف، استفراغ، یبوست، اتساع؛ استفراغ پرتابی بعد از شیر: تنگی پیلور (سونوگرافی)؛ توده کشاله ران: فتق گیرافتاده (شایع در نارس)"],"ddx":[{"n":"Malrotation with midgut volvulus |","cm":1},{"n":"Necrotizing enterocolitis |","cm":1},{"n":"Sepsis / UTI / meningitis |","cm":1},{"n":"Pyloric stenosis |"},{"n":"Incarcerated inguinal hernia |"},{"n":"Anal fissure / Hirschsprung disease |"},{"n":"Inborn error of metabolism |"}],"redflags":["استفراغ صفراوی، اتساع با بی‌حالی/تب، مدفوع خونی با علائم سپسیس"],"guide":"نوزاد با رشد خوب و regurgitation: اطمینان‌بخشی. استفراغ صفراوی: مشاوره فوری جراحی اطفال و سری فوقانی دستگاه گوارش با follow-through روده کوچک. تنگی پیلور: سونوگرافی. فتق گیرافتاده: جراح. نوزاد دهیدراته: بستری و مایع تزریقی. NEC: شک → سپسیس ورک‌آپ و جراح.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 67: Common Neonatal Problems, pp. 361–365"},"neonatal-resp-neuro":{"id":"neonatal-resp-neuro","variants":[{"id":"neonate-apnea-brue","o":{"L":[{"t":"Electrolytes, calcium, phosphorous, magnesium, ammonia; urine toxicological screen; testing for respiratory syncytial virus or pertussis; sepsis workup including blood, urine and cerebrospinal fluid"}],"I":[{"t":"Brain CT in cases of suspected nonaccidental trauma"}],"Co":[{"t":"Admission for monitoring and treatment"}]},"name":"Neonatal apnea / higher-risk BRUE","level":"I","imp":"Neonatal apnea / BRUE (higher risk)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"شیرخوار ۳۵ روزه با دوره آپنه و سیانوز در خانه که حل شده است.","why":"آپنه نشانه بیماری بحرانی؛ ورک‌آپ و بستری با مانیتور."},{"id":"neonate-brue-low","o":{"T":[{"t":"Nasal saline drops and nasal suctioning for nasal congestion","fl":[{"k":"note","v":"no further orders given for low-risk BRUE"}]}],"Co":[{"t":"Close follow-up"}]},"name":"Lower-risk BRUE / colic / periodic breathing","level":"III","imp":"Lower-risk BRUE / colic","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"شیرخوار ۹۰ روزه با اولین حادثه ۳۰ ثانیه‌ای تغییر رنگ؛ حال فعلی خوب.","why":"کم‌خطر: ارزیابی محدود و پیگیری؛ کولیک تشخیص رد است."},{"id":"neonate-seizure","o":{"L":[{"t":"Serum calcium level and extensive workup","fl":[{"k":"note","v":"other tests not specified in this chapter"}]}],"Co":[{"t":"Admission"}]},"name":"Neonatal seizure","level":"I","imp":"Neonatal seizure","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"نوزاد ۱۰ روزه با انحراف چشم، پلک‌زدن و حرکات پدالی.","why":"همه تشنج‌های نوزاد ورک‌آپ وسیع و بستری می‌خواهند."}],"ch":"67","name":"Neonatal apnea, crying, colic, seizures and BRUE","name_fa":"آپنه، گریه، کولیک، تشنج و BRUE در نوزاد","cc":["pediatric-respiratory","pediatric-other"],"keywords":"neonatal apnea, periodic breathing, laryngomalacia, colic, neonatal seizure, benign neonatal sleep myoclonus, BRUE, ALTE, SIDS, آپنه نوزاد","status":"draft","features":["تنفس طبیعی نوزاد 30 تا 60/min؛ periodic breathing (مکث < 5 تا 10 ثانیه) معمولاً طبیعی؛ آپنه: توقف تنفس > 10 تا 20 ثانیه با یا بدون برادی‌کاردی و سیانوز: بیماری بحرانی (عفونت، CNS، متابولیک)؛ ممکن است اولین علامت برونشیولیت RSV؛ کلامیدیا و سیاه‌سرفه","تنفس پرسروصدا معمولاً خوش‌خیم؛ استریدور نوزاد: آنومالی مادرزادی (laryngomalacia شایع‌ترین)؛ گرفتگی بینی: نوزاد اجباراً از بینی تنفس می‌کند؛ قطره سالین و ساکشن","گریه طولانی: بی‌قراری واقعی جدی است: آسیب (اتفاقی یا عمدی)، عفونت، SVT، خراش قرنیه، hair tourniquet، فتق یا torsion، اورژانس شکمی؛ اگر پس از ارزیابی علت پیدا نشد و ادامه داشت: بستری","کولیک: حدود 13٪ نوزادان؛ گریه ≥ 3 ساعت/روز ≥ 3 روز/هفته طی 3 هفته؛ بعد از 3 ماه تمام می‌شود؛ تشخیص رد؛ درمان مؤثر ندارد","تشنج نوزاد: علائم ظریف (انحراف چشم، بیرون آوردن زبان، پلک‌زدن، آپنه، حرکات پدالی، قوس)؛ همه نیاز به ورک‌آپ کامل شامل کلسیم سرم و بستری دارند؛ افتراق از رفلکس Moro و benign neonatal sleep myoclonus (فقط در خواب، با لمس قطع می‌شود، بی‌نیاز از ورک‌آپ)","ALTE/BRUE: < 12 ماه، حادثه کوتاه حل‌شده با سیانوز/رنگ‌پریدگی، تنفس غیرمنظم/کاهش/قطع، هیپر/هیپوتونی یا تغییر پاسخ‌دهی؛ ظاهر خوب و بدون توضیح؛ کم‌خطر: > 60 روز، سن بارداری ≥ 32 هفته و پس از لقاح ≥ 45 هفته، اولین حادثه، < 1 دقیقه، بدون CPR، بدون یافته نگران‌کننده؛ در غیر این صورت پرخطر؛ ارتباطی با SIDS ندارد"],"ddx":[{"n":"Sepsis / meningitis |","cm":1},{"n":"SVT / cardiac disease |","cm":1},{"n":"Seizure |","cm":1},{"n":"Bronchiolitis (RSV) / pertussis / chlamydia |"},{"n":"Nonaccidental trauma |"},{"n":"Colic / corneal abrasion / hair tourniquet |"}],"redflags":["آپنه، تشنج، بی‌قراری واقعی، BRUE پرخطر"],"guide":"آپنه: بررسی فوری و بستری با مانیتور. BRUE پرخطر: CBC؛ الکترولیت، کلسیم، فسفر، منیزیم و آمونیاک؛ غربال توکسیکولوژی ادرار؛ CXR؛ ECG؛ تست RSV یا سیاه‌سرفه؛ ورک‌آپ سپسیس (خون، ادرار، CSF)؛ CT مغز در شک NAT. تشنج نوزاد: کلسیم سرم و ورک‌آپ وسیع و بستری.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 67: Common Neonatal Problems, pp. 361–365"},"neonatal-jaundice-skin-eye":{"id":"neonatal-jaundice-skin-eye","variants":[{"id":"neonate-jaundice-serious","o":{"L":[{"t":"Total and direct bilirubin, liver function tests, reticulocyte count, Coombs test, peripheral blood smear, complete sepsis evaluation including lumbar puncture"}],"A":[{"t":"Empiric antibiotics when sepsis is suspected","fl":[{"k":"note","v":"drug and dose not given in this chapter; see Chapter 66"}]}],"Co":[{"t":"Admission; phototherapy per bilitool.org"}]},"name":"Neonatal jaundice, concerning (< 24 h or after day 3)","level":"II","imp":"Neonatal jaundice (concerning)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"نوزاد ۷ روزه با ایکتر شدید، تغذیه ضعیف و تب.","why":"ایکتر بعد از روز سوم معمولاً جدی؛ ورک‌آپ سپسیس."},{"id":"neonate-thrush-diaper","o":{"T":[{"t":"Oral nystatin suspension topically four times a day (thrush)"},{"t":"Contact dermatitis: frequent diaper changes, air drying, barrier cream containing zinc oxide"},{"t":"Candidal dermatitis: frequent diaper changes and Nystatin cream at least four times a day"}]},"name":"Oral thrush / diaper rash","level":"III","imp":"Oral thrush / diaper dermatitis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"نوزاد ۲۰ روزه با پلاک سفید دهانی و قرمزی ناحیه پوشک.","why":"nystatin خوراکی/موضعی؛ پوشک تماسی: کرم مانع."},{"id":"neonate-eye","o":{"L":[{"t":"Fluorescein staining (corneal abrasion); sepsis workup if gonococcal conjunctivitis"}],"A":[{"t":"Parenteral antibiotics","if":"gonococcal conjunctivitis","fl":[{"k":"note","v":"drug and dose not given in this chapter"}]},{"t":"Oral erythromycin","if":"chlamydial conjunctivitis, after the first week","fl":[{"k":"note","v":"dose not given in this chapter; topical drops inadequate"}]}],"T":[{"t":"Ocular irrigation (gonococcal)"}],"Co":[{"t":"Prompt pediatric ophthalmology consultation (cloudy cornea suggests acute glaucoma); admission for gonococcal conjunctivitis"}]},"name":"Neonatal red eye / conjunctivitis","level":"II","imp":"Neonatal conjunctivitis / red eye","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"نوزاد ۳ روزه با ترشح چرکی فراوان چشم.","why":"گنوکوک: ورک‌آپ سپسیس و آنتی‌بیوتیک تزریقی؛ کلامیدیا: erythromycin خوراکی."}],"ch":"67","name":"Neonatal jaundice, thrush, diaper rash and eye complaints","name_fa":"ایکتر، برفک، التهاب پوشک و مشکلات چشم نوزاد","cc":["jaundice","pediatric-other","eye"],"keywords":"neonatal jaundice, phototherapy, bilitool, oral thrush, nystatin, diaper rash, gonococcal conjunctivitis, chlamydial conjunctivitis, erythromycin, ایکتر نوزاد","status":"draft","features":["ایکتر در 24 ساعت اول: جدی (معمولاً در نوزادگاه)؛ روز 2 تا 3: معمولاً فیزیولوژیک اگر وزن‌گیری، تغذیه و مدفوع خوب، بدون کم‌خونی، بیلی‌روبین دایرکت ≤ 1/3 توتال و توتال نیازمند فتوتراپی نیست (bilitool.org)؛ بعد از روز 3: معمولاً جدی (سپسیس، UTI، TORCH، همولیز، آترزی صفراوی، شیر مادر، کم‌کاری تیروئید)","برفک: ضایعات سفید پنیری زبان، لب، لثه، مخاط گونه؛ nystatin","التهاب پوشک: تماسی (ماکولار، اریتماتو و لبه تیز) و کاندیدایی (پلاک اریتماتو با لبه scalloped و ضایعات ماهواره‌ای)","چشم: خراش قرنیه (فلورسئین)؛ قرنیه کدر = گلوکوم حاد (چشم‌پزشکی اطفال)؛ گنوکوک در روزهای اول با ترشح فراوان؛ کلامیدیا بعد از هفته اول"],"ddx":[{"n":"Sepsis / UTI (jaundice after day 3) |","cm":1},{"n":"Biliary atresia / hemolytic anemia |","cm":1},{"n":"Gonococcal conjunctivitis |","cm":1},{"n":"Physiologic jaundice / breast milk jaundice |"},{"n":"Contact vs candidal diaper dermatitis |"},{"n":"Corneal abrasion / acute glaucoma |"}],"redflags":["ایکتر روز اول یا بعد از روز 3، قرنیه کدر، ترشح چرکی فراوان چشم"],"guide":"ایکتر جدی: ورک‌آپ کامل سپسیس شامل LP، اسمیر خون محیطی، CBC، بیلی‌روبین توتال و دایرکت، LFT، رتیکولوسیت و Coombs؛ آنتی‌بیوتیک تجربی در شک به سپسیس. برفک: nystatin suspension خوراکی 4 بار روزانه. پوشک تماسی: تعویض مکرر، هوا‌دهی و کرم مانع حاوی zinc oxide؛ کاندیدایی: تعویض مکرر و nystatin cream حداقل 4 بار روزانه. گنوکوک: ورک‌آپ سپسیس، شست‌وی چشم، آنتی‌بیوتیک تزریقی، چشم‌پزشکی و بستری؛ کلامیدیا: قطره موضعی ناکافی، erythromycin خوراکی.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 67: Common Neonatal Problems, pp. 361–365"},"neonatal-metabolic-cardiac-nat":{"id":"neonatal-metabolic-cardiac-nat","variants":[{"id":"neonate-cah-shock","o":{"L":[{"t":"Serum ammonia added to the usual laboratories obtained during resuscitation (inborn errors of metabolism); electrolytes (hyponatremia and hyperkalemia in CAH)"}],"T":[{"t":"Hydrocortisone 12.5 to 25 mg IV, IM or IO (congenital adrenal hyperplasia), in addition to usual resuscitation measures"}],"Co":[{"t":"Admission; PICU"}]},"name":"Congenital adrenal hyperplasia / inborn error with shock","level":"I","imp":"Neonatal shock (congenital adrenal hyperplasia / inborn error of metabolism)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"نوزاد ۱۰ روزه با ژنیتال مبهم، هیپرپیگمانتاسیون، شوک، Na پایین و K بالا.","why":"CAH: هیدروکورتیزون به علاوه احیا؛ IEM: آمونیاک."},{"id":"neonate-cyanosis","o":{"Co":[{"t":"Admit all cyanotic neonates for monitoring, therapy and further investigation"}]},"name":"Cyanotic neonate (suspected congenital heart disease)","level":"I","imp":"Cyanosis in neonate (suspected congenital heart disease)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","o2":"O2 therapy: oxygen; cyanosis unresponsive to oxygen suggests cyanotic heart disease","sc":"نوزاد ۵ روزه با سیانوز و تنفس سریع بدون زحمت که با اکسیژن بهبود نمی‌یابد.","why":"بیماری قلبی سیانوتیک مطرح؛ بستری و بررسی."},{"id":"neonate-nat","o":{"I":[{"t":"Computed tomography of the head (intracranial injuries); retinal examination","fl":[{"k":"note","v":"other imaging per Chapter 187"}]}],"Co":[{"t":"Admission; child protection / social work"}]},"name":"Suspected nonaccidental trauma in neonate / infant","level":"I","imp":"Suspected nonaccidental trauma","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"شیرخوار ۳ ماهه با بی‌حالی و کبودی‌های مختلف.","why":"NAT را با CT سر و معاینه شبکیه بررسی کن."}],"ch":"67","name":"Inborn errors of metabolism, congenital adrenal hyperplasia, cyanotic heart disease and nonaccidental trauma in neonates","name_fa":"IEM، هیپرپلازی مادرزادی آدرنال، بیماری قلبی سیانوتیک و ترومای غیرتصادفی در نوزاد","cc":["pediatric-other","hypotension-shock","abuse-assault"],"keywords":"inborn error of metabolism, ammonia, congenital adrenal hyperplasia, hydrocortisone, cyanotic heart disease, right-to-left shunt, nonaccidental trauma, abusive head trauma, هیپرپلازی آدرنال","status":"draft","features":["IEM: بی‌حالی یا ایست قلبی‌تنفسی؛ اغلب پس از احیا تشخیص داده می‌شود؛ آمونیاک سرم به آزمایش‌های احیا اضافه شود","CAH: ویریلیزاسیون، ژنیتال مبهم، هیپرپیگمانتاسیون؛ ممکن است شوک؛ هیپوناترمی و هیپرکالمی","سیانوز: تنفس سریع بدون زحمت و عدم پاسخ به اکسیژن: بیماری قلبی سیانوتیک (shunt راست به چپ)؛ تنفس نامنظم/سطحی: سپسیس، CNS، متابولیک؛ تنفس زحمت‌دار با grunting و retraction: ریوی (پنومونی، برونشیولیت)؛ همه سیانوتیک‌ها بستری","NAT: کبودی‌های با سنین مختلف بدون توضیح، شکستگی جمجمه، آسیب داخل جمجمه در CT، شکستگی اندام، سوختگی سیگار، خونریزی شبکیه، تحریک‌پذیری، بی‌حالی یا کما"],"ddx":[{"n":"Adrenal crisis |","cm":1},{"n":"Cyanotic congenital heart disease |","cm":1},{"n":"Inborn error of metabolism |","cm":1},{"n":"Sepsis |"},{"n":"Nonaccidental trauma |"}],"redflags":["شوک، هیپوناترمی/هیپرکالمی، سیانوز بی‌پاسخ به اکسیژن"],"guide":"IEM: آمونیاک سرم در کنار آزمایش‌های احیا. CAH: علاوه بر احیای معمول: hydrocortisone IV/IM/IO با دوز 12.5 تا 25 mg. سیانوز: بستری برای مانیتور، درمان و بررسی.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 67: Common Neonatal Problems, pp. 361–365"},"acute-otitis-media-peds":{"id":"acute-otitis-media-peds","variants":[{"id":"aom-uncomplicated","o":{"T":[{"t":"Benzocaine-antipyrine topical analgesic (unless known perforation of the tympanic membrane)"},{"t":"Acetaminophen 15 mg/kg or Ibuprofen 10 mg/kg"}],"A":[{"t":"Amoxicillin 40 to 45 mg/kg/dose PO twice daily (first choice); or wait-and-see prescription (fill if not better or worse within 48 to 72 hours)","fl":[{"k":"ci","v":"no wait-and-see if age < 6 months, immunocompromised, ill-appearing, recent antibiotics, or another bacterial infection"}]},{"t":"Second-line: Amoxicillin/clavulanate 40 to 45 mg/kg/dose (amoxicillin component) twice daily; Cefpodoxime 5 mg/kg/dose twice daily; Cefuroxime 15 mg/kg/dose twice daily; Cefdinir 7 mg/kg/dose twice daily; Ceftriaxone 50 mg/kg/dose IM for one to three daily doses"},{"t":"Allergic to the above: Azithromycin 10 mg/kg/dose PO on the first day followed by 5 mg/kg/dose PO for four more days"}],"Co":[{"t":"Routine follow-up not necessary unless symptoms persist or worsen"}]},"name":"Uncomplicated acute otitis media","level":"III","imp":"Acute otitis media","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"کودک ۱۲ ماهه با تب، گریه و کشیدن گوش؛ پرده برجسته.","why":"AOM بدون عارضه: ضددرد و آموکسی‌سیلین یا wait-and-see."},{"id":"aom-mastoiditis-infant","o":{"I":[{"t":"CT scan of the mastoid if mastoiditis is suspected"}],"L":[{"t":"Infant < 60 days with AOM: evaluation for presumed sepsis (see Chapter 66)"}],"A":[{"t":"Parenteral antibiotics (confirmed mastoiditis)","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Otorhinolaryngology consultation; mastoiditis typically requires inpatient treatment"}]},"name":"Mastoiditis or AOM in an infant younger than 60 days","level":"II","imp":"Mastoiditis / otitis media in young infant","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"کودک ۲ ساله با تب و بیرون‌زدگی لاله و تندرنس ماستوئید.","why":"ماستوییدیت: CT و آنتی‌بیوتیک تزریقی؛ شیرخوار < 60 روز: درمان سپسیس."}],"ch":"68","name":"Acute otitis media and mastoiditis in children","name_fa":"اوتیت میانی حاد و ماستوییدیت در کودکان","cc":["ent","pediatric-fever"],"keywords":"acute otitis media, AOM, mastoiditis, amoxicillin, wait-and-see prescription, bullous myringitis, tympanic membrane, اوتیت میانی","status":"draft","features":["7.4٪ ویزیت‌های ED در ایالات متحده؛ شایع در کودکان به‌علت نابالغی شیپور استاش؛ عوامل: S. pneumoniae (49٪) و H. influenzae غیرقابل تیپ (29٪)","اوج سنی 6 تا 18 ماه؛ تب، تغذیه ضعیف، تحریک‌پذیری، استفراغ، کشیدن گوش و درد گوش","علائم: برجستگی و چرک پشت پرده، بی‌حرکتی پرده تمپان، از دست رفتن نشانه‌های استخوانی و bullae (bullous myringitis)","ماستوییدیت: شایع‌ترین عارضه چرکی؛ تب، بیرون‌زدگی لاله و تندرنس ماستوئید","تشخیص نیازمند سه جزء: شروع حاد (< 48 ساعت)، افیوژن گوش میانی، علائم التهاب گوش میانی؛ قرمزی پرده به‌تنهایی کافی نیست (تب و گریه)؛ اتوسکوپی پنوماتیک مفید","افتراق: جسم خارجی مجرا و اوتیت اکسترنا"],"ddx":[{"n":"Mastoiditis |","cm":1},{"n":"Sepsis in infant < 60 days |","cm":1},{"n":"Otitis externa / foreign body in ear canal |"},{"n":"Viral upper respiratory infection |"}],"redflags":["بیرون‌زدگی لاله و تندرنس ماستوئید، شیرخوار < 60 روز، ظاهر بدحال"],"guide":"درد: بنزوکائین-آنتی‌پیرین موضعی (مگر سوراخ‌شدگی پرده) و acetaminophen 15 mg/kg یا ibuprofen 10 mg/kg. «wait-and-see prescription» در AOM بدون عارضه: اگر در 48 تا 72 ساعت بهتر نشد نسخه گرفته شود؛ ممنوع: < 6 ماه، نقص ایمنی، ظاهر بدحال، آنتی‌بیوتیک اخیر یا عفونت باکتریال دیگر. خط اول: amoxicillin 40 تا 45 mg/kg/dose PO دو بار روزانه. خط دوم: amoxicillin/clavulanate 40–45 mg/kg/dose (جزء آموکسی‌سیلین) دو بار روزانه؛ cefpodoxime 5 mg/kg/dose دو بار روزانه؛ cefuroxime 15 mg/kg/dose دو بار روزانه؛ cefdinir 7 mg/kg/dose دو بار روزانه؛ ceftriaxone 50 mg/kg/dose IM یک تا سه دوز روزانه؛ حساسیت: azithromycin 10 mg/kg/dose روز اول سپس 5 mg/kg/dose چهار روز. < 60 روز: ارزیابی و درمان به‌عنوان سپسیس (GBS، S. aureus، گرم‌منفی). علائم 48 تا 72 ساعته بهبود می‌یابد؛ افیوژن تا 8 تا 12 هفته. ماستوییدیت: CT ماستوئید، مشاوره ENT و آنتی‌بیوتیک تزریقی؛ بستری.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 68: Common Infections of the Ears, Nose, Neck, and Throat, pp. 366–371"},"otitis-externa-peds":{"id":"otitis-externa-peds","variants":[{"id":"oe-uncomplicated","o":{"T":[{"t":"Clean the ear canal with a small tuft of cotton attached to a wire applicator; wick in the canal if significant edema obstructs the canal"},{"t":"Ibuprofen 10 mg/kg/dose every 6 hours"},{"t":"Ciprofloxacin with hydrocortisone 0.2% and 1% suspension (Cipro HC) 3 drops twice daily, or Ofloxacin 0.3% solution 5 to 10 drops twice daily (ofloxacin when TM rupture is found or suspected)"}],"A":[{"t":"oral antibiotics","if":"auricular cellulitis","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Follow-up if no improvement within 48 hours; malignant otitis externa: hospitalization with parenteral antibiotics"}]},"name":"Otitis externa","level":"III","imp":"Otitis externa","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"پسر ۹ ساله پس از شنا با درد گوش و درد با کشیدن لاله.","why":"تمیز کردن و قطره فلوروکینولون."}],"ch":"68","name":"Otitis externa in children","name_fa":"اوتیت اکسترنا در کودکان","cc":["ent"],"keywords":"otitis externa, swimmer's ear, ciprofloxacin hydrocortisone, ofloxacin otic, malignant otitis externa, wick, اوتیت اکسترنا","status":"draft","features":["التهاب لاله، مجرای گوش خارجی و سطح پرده؛ P. aeruginosa و S. aureus (اغلب همراه)","بهار و تابستان؛ اوج 7 تا 12 سال؛ درد گوش، خارش، گاهی تب؛ اریتم و ادم مجرا، اگزودای سفید، درد با حرکت تراگوس/لاله، آدنوپاتی پریاوریکولار/گردنی","تشخیص بالینی؛ جسم خارجی را با برداشتن دقیق دبری رد کن","اوتیت اکسترنای بدخیم: علائم سیستمیک و سلولیت لاله؛ بستری و آنتی‌بیوتیک تزریقی"],"ddx":[{"n":"Malignant otitis externa |","cm":1},{"n":"Foreign body in the ear canal |"},{"n":"Acute otitis media |"}],"redflags":["علائم سیستمیک و سلولیت لاله"],"guide":"اول تمیز کردن مجرا با پنبه روی سیم؛ در ادم انسدادی wick. ضددرد: ibuprofen 10 mg/kg/dose هر 6 ساعت. قطره فلوروکینولون ترجیح بر نئومایسین: ciprofloxacin با hydrocortisone (Cipro HC) 0.2٪ و 1٪ سوسپانسیون 3 قطره دو بار روزانه یا ofloxacin 0.3٪ 5 تا 10 قطره دو بار روزانه (ofloxacin در پارگی یا شک به پارگی پرده). آنتی‌بیوتیک خوراکی در سلولیت لاله. پیگیری اگر در 48 ساعت بهتر نشد.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 68: Common Infections of the Ears, Nose, Neck, and Throat, pp. 366–371"},"sinusitis-peds":{"id":"sinusitis-peds","variants":[{"id":"sinusitis-peds-main","o":{"A":[{"t":"Mild to moderate: Amoxicillin 40 to 45 mg/kg/dose PO twice daily for 10 to 14 days"},{"t":"Severe symptoms, day care or recent antibiotics: Amoxicillin/clavulanate 40 to 45 mg/kg/dose twice a day (amoxicillin component), or Cefuroxime 15 mg/kg PO twice a day, or Cefpodoxime 5 mg/kg PO twice a day"}],"Co":[{"t":"Mild symptoms suggestive of viral infection: observe 7 to 10 days, no antibiotics"}]},"name":"Acute bacterial sinusitis","level":"III","imp":"Acute bacterial sinusitis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"کودک ۵ ساله با ترشح چرکی بینی ۴ روزه، تب 39.5 و ظاهر بدحال.","why":"علائم پایدار یا شدید: آنتی‌بیوتیک؛ خفیف: مشاهده."}],"ch":"68","name":"Acute bacterial sinusitis in children","name_fa":"سینوزیت باکتریال حاد در کودکان","cc":["ent","pediatric-fever"],"keywords":"sinusitis, amoxicillin, amoxicillin clavulanate, purulent nasal drainage, سینوزیت","status":"draft","features":["التهاب سینوس‌های پاراناسال؛ سینوزیت باکتریال حاد: عفونت با بهبود کامل < 30 روز؛ عوامل: S. pneumoniae، M. catarrhalis و H. influenzae غیرقابل تیپ","حاد شدید: تب، سردرد و تورم/تندرنس/اریتم موضعی (نوجوانان بزرگ‌تر)؛ تحت‌حاد خفیف: عفونت تنفسی فوقانی طولانی با ترشح چرکی بینی > 2 هفته؛ تب نادر","تشخیص بالینی بدون آزمایش/تصویربرداری؛ احتقان 3 تا 7 روز با عفونت ویروسی: سینوزیت نیست و آنتی‌بیوتیک ندارد؛ ترشح رنگی بینی به‌تنهایی نشانه نیست؛ تصویربرداری در < 6 سال لازم نیست"],"ddx":[{"n":"Orbital cellulitis / intracranial extension |","cm":1},{"n":"Viral upper respiratory infection |"},{"n":"Allergic rhinitis |"}],"redflags":["تب > 39°C، ترشح چرکی > 3 روز و ظاهر بدحال"],"guide":"خفیف مشابه ویروسی: 7 تا 10 روز مشاهده بدون آنتی‌بیوتیک. خفیف تا متوسط: amoxicillin 40 تا 45 mg/kg/dose PO دو بار روزانه 10 تا 14 روز. شدید، مهدکودک یا آنتی‌بیوتیک اخیر: amoxicillin/clavulanate 40 تا 45 mg/kg/dose دو بار روزانه یا cefuroxime 15 mg/kg PO دو بار روزانه یا cefpodoxime 5 mg/kg PO دو بار روزانه.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 68: Common Infections of the Ears, Nose, Neck, and Throat, pp. 366–371"},"pharyngitis-stomatitis-peds":{"id":"pharyngitis-stomatitis-peds","variants":[{"id":"pharyngitis-gabhs","o":{"L":[{"t":"Rapid antigen detection test and/or throat culture if two or more Centor criteria; confirmatory throat culture if rapid antigen is negative"}],"A":[{"t":"Penicillin V (children 250 mg PO twice daily; adolescent/adult 500 mg PO twice daily) for 7 to 10 days; or Benzathine penicillin G 1.2 million units IM (600,000 units IM if weight < 27 kg) once; or Amoxicillin 50 mg/kg once daily for 7 to 10 days"}],"T":[{"t":"Ibuprofen and acetaminophen (systemic analgesics)","fl":[{"k":"note","v":"doses per child weight, see Chapter 66"}]}]},"name":"Streptococcal pharyngitis (GABHS)","level":"III","imp":"Group A streptococcal pharyngitis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"دختر ۸ ساله با گلودرد، تب، اگزودای لوزه و بدون سرفه.","why":"Centor ≥ 2: تست آنتی‌ژن سریع؛ مثبت: پنی‌سیلین."},{"id":"stomatitis-viral-ebv","o":{"S":[{"t":"Parenteral hydration","if":"cannot tolerate oral fluids","fl":[{"k":"note","v":"volume not given in the book"}]}],"T":[{"t":"Systemic analgesics: combination of ibuprofen and acetaminophen; occasionally oral narcotics may be required","fl":[{"k":"note","v":"doses per weight"}]},{"t":"EBV: antipyretics, fluids and rest; monospot (may be negative in first week or < 2 years)"}]},"name":"Herpangina / HFMD / HSV gingivostomatitis / EBV (supportive)","level":"III","imp":"Viral stomatitis / pharyngitis (herpangina, HFMD, HSV, EBV)","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"کودک ۳ ساله با تب و وزیکول دردناک کام و امتناع از نوشیدن.","why":"حمایتی؛ هیدراتاسیون وریدی اگر مایع خوراکی تحمل نشود."},{"id":"pharyngitis-gonococcal","o":{"L":[{"t":"Culture on Thayer-Martin medium; vaginal, cervical, urethral and rectal cultures"}],"A":[{"t":"Ceftriaxone 250 mg IM; Azithromycin 1 g PO given in the emergency department (empiric chlamydia treatment)"}],"Co":[{"t":"Appropriate follow-up for treatment failure and symptomatic contacts; local reporting agencies and social service investigation"}]},"name":"Gonococcal pharyngitis","level":"II","imp":"Gonococcal pharyngitis (consider sexual abuse)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"نوجوان ۱۴ ساله با گلودرد و کشت Thayer-Martin مثبت.","why":"در کودک و نوجوان غیرفعال جنسی سوءاستفاده جنسی را مطرح کن."}],"ch":"68","name":"Pediatric stomatitis and pharyngitis (herpangina, HFMD, HSV gingivostomatitis, GABHS, EBV, gonococcal)","name_fa":"استوماتیت و فارنژیت کودکان (هرپانژین، HFMD، هرپس، استرپتوکوک، EBV، گنوکوک)","cc":["ent","pediatric-fever"],"keywords":"pharyngitis, strep throat, GABHS, Centor criteria, rapid antigen test, penicillin V, benzathine penicillin, herpangina, hand foot and mouth, infectious mononucleosis, EBV, گلودرد","status":"draft","features":["هرپانژین، HFMD و گینگیوواستوماتیت هرپسی ویروسی‌اند؛ بیشتر فارنژیت ویروسی؛ GABHS و N. gonorrhoeae باکتریال: تشخیص دقیق لازم؛ درمان GABHS از عوارض چرکی و تب روماتیسمی پیشگیری می‌کند","هرپانژین: وزیکول‌های بنایی لوزه و کام نرم؛ 6 ماه تا 10 سال؛ اواخر تابستان تا پاییز؛ درد، تب، دیسفاژی","HFMD: ماکول تا وزیکول در کام، مخاط گونه، لثه و زبان و کف دست/پا و باسن","هرپس گینگیوواستوماتیت: شروع ناگهانی تب، تحریک‌پذیری، کاهش دریافت خوراکی، لثه ادماتو و شکننده، وزیکول و زخم قدام دهان","GABHS: اواخر زمستان/اوایل بهار؛ 5 تا 15 سال؛ نادر قبل از 2 سال؛ گلودرد، تب، سردرد، درد شکم، آدنوپاتی قدامی گردن، پتشی کام و هیپرتروفی لوزه؛ معمولاً بدون سرفه، آبریزش بینی، لارنژیت، استریدور، ملتحمه و اسهال؛ راش اسکارلاتینی","EBV: تب، گلودرد، بی‌حالی؛ آدنوپاتی (اغلب خلفی)، هپاتواسپلنومگالی؛ مشکوک اگر فارنژیت بدون پاسخ به آنتی‌بیوتیک با کشت منفی؛ monospot ممکن است < 2 سال و هفته اول منفی باشد؛ لنفوسیتوز با لنفوسیت آتیپیک","فارنژیت گنوکوکی در کودک یا نوجوان غیرفعال جنسی: سوءاستفاده جنسی را مطرح کن؛ کشت Thayer-Martin و کشت واژن، سرویکس، مجرا و رکتوم","Centor: اگزودای لوزه، آدنوپاتی قدامی دردناک، نبود سرفه، سابقه تب؛ ≥ 2 → تست آنتی‌ژن سریع و/یا کشت؛ منفی: کشت تأییدی"],"ddx":[{"n":"Epiglottitis / retropharyngeal or peritonsillar abscess |","cm":1},{"n":"Gonococcal pharyngitis (sexual abuse) |","cm":1},{"n":"Group A streptococcal pharyngitis |"},{"n":"Infectious mononucleosis (EBV) |"},{"n":"Viral pharyngitis / herpangina / HFMD |"}],"redflags":["ترشح بزاق (drooling)، استریدور، ترسمیس، ناتوانی در نوشیدن"],"guide":"هرپانژین/HFMD/HSV: حمایتی؛ ضددرد سیستمیک (ibuprofen و acetaminophen)؛ هیدراتاسیون وریدی اگر مایعات خوراکی تحمل نشود؛ گاهی مخدر خوراکی. GABHS: آنتی‌بیوتیک فقط با تست سریع یا کشت مثبت: penicillin V (کودک 250 mg PO دو بار روزانه؛ نوجوان/بزرگسال 500 mg دو بار روزانه) 7 تا 10 روز؛ benzathine penicillin G 1.2 میلیون واحد IM (600000 واحد زیر 27 kg) یک‌بار؛ amoxicillin 50 mg/kg یک‌بار در روز 7 تا 10 روز. گنوکوک: ceftriaxone 250 mg IM و azithromycin 1 g PO در ED؛ گزارش به مراجع محلی و بررسی اجتماعی. EBV: حمایتی (تب‌بر، مایع و استراحت).","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 68: Common Infections of the Ears, Nose, Neck, and Throat, pp. 366–371"},"cervical-lymphadenitis-peds":{"id":"cervical-lymphadenitis-peds","variants":[{"id":"lymphadenitis-acute","o":{"A":[{"t":"Amoxicillin plus clavulanic acid 20 mg/kg/dose twice daily, or Clindamycin 10 mg/kg/dose three times daily for 7 to 10 days"}],"T":[{"t":"Incision and drainage if a fluctuant mass is present"},{"t":"Acute bilateral lymphadenitis: most resolve without antibiotics (viral or reactive)"}]},"name":"Acute unilateral cervical lymphadenitis","level":"III","imp":"Acute cervical lymphadenitis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"پسر ۴ ساله با گره تندر یک‌طرفه گردن 2 cm و اریتم.","why":"S. aureus یا استرپتوکوک: آموکسی‌سیلین-کلاولانات یا کلیندامایسین؛ درناژ در فلوکتواسیون."}],"ch":"68","name":"Cervical lymphadenitis in children","name_fa":"لنفادنیت گردنی در کودکان","cc":["ent","pediatric-other"],"keywords":"cervical lymphadenitis, neck mass, Bartonella, cat scratch, clindamycin, amoxicillin clavulanate, sialadenitis, لنفادنیت گردن","status":"draft","features":["یک‌طرفه حاد: S. aureus یا استرپتوکوک گروه A؛ دوطرفه: ویروسی (EBV، آدنوویروس)؛ مزمن: Bartonella henselae یا مایکوباکتریوم","حاد: گره‌های تندر > 1 cm با اریتم؛ دوطرفه: گره‌های کوچک لاستیکی، خودبه‌خود بهبود؛ Bartonella: خراش بچه‌گربه و لنفادنیت هم‌طرف","تشخیص بالینی؛ کشت راهنمای درمان؛ افتراق: سیالادنیت (S. aureus، گرم‌منفی، بی‌هوازی)"],"ddx":[{"n":"Deep neck abscess |","cm":1},{"n":"Sialadenitis |"},{"n":"Viral reactive lymphadenopathy |"},{"n":"Bartonella / mycobacterial lymphadenitis |"}],"redflags":["توده فلوکتوان، ترسمیس، دیسترس راه هوایی"],"guide":"خط اول لنفادنیت حاد: amoxicillin + clavulanic acid 20 mg/kg/dose دو بار روزانه یا clindamycin 10 mg/kg/dose سه بار روزانه 7 تا 10 روز. توده فلوکتوان ممکن است نیاز به برش و درناژ داشته باشد. دوطرفه حاد معمولاً بدون آنتی‌بیوتیک بهبود می‌یابد. مزمن: اغلب جراحی با درمان هدفمند.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 68: Common Infections of the Ears, Nose, Neck, and Throat, pp. 366–371"},"viral-croup":{"id":"viral-croup","variants":[{"id":"croup-mild","o":{"T":[{"t":"Dexamethasone 0.15 to 0.6 mg/kg (maximum 10 mg) PO or IM (the IV formulation may be given orally); or nebulized Budesonide 2 mg if unable to tolerate oral treatment"},{"t":"Position of comfort with minimal disturbance; monitor pulse oximetry"}],"Co":[{"t":"Discharge when criteria met (≥ 3 hours since last epinephrine, nontoxic, no dehydration, room air SpO2 > 90%, parents able to recognize changes, short transit time)"}]},"name":"Mild croup","level":"III","imp":"Viral croup","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: only if SpO2 < 94%, nasal cannula or face mask with flow by age and weight; keep the child in a position of comfort","sc":"کودک ۲ ساله با سرفه پارس‌دار و استریدور فقط هنگام گریه.","why":"استروئید تک‌دوز حتی در خفیف؛ epinephrine لازم نیست."},{"id":"croup-moderate-severe","o":{"I":[{"t":"Neck or chest radiographs only if other causes are being considered (subglottic narrowing, \"steeple sign\")"}],"T":[{"t":"Dexamethasone 0.15 to 0.6 mg/kg (maximum 10 mg) PO or IM"},{"t":"Nebulized racemic Epinephrine 2.25% 0.05 mL/kg/dose up to 0.5 mL; or L-epinephrine (1:1000) 0.5 mL/kg/dose up to 5 mL"},{"t":"Heliox (70% helium/30% oxygen) for severe refractory croup (no definitive advantage)"},{"t":"Intubation when clinically indicated, consider a smaller endotracheal tube than estimated by age"}],"Co":[{"t":"Admit children with persistent stridor at rest, tachypnea, retractions, hypoxia, or those requiring more than two epinephrine treatments"}]},"name":"Moderate to severe croup (stridor at rest)","level":"II","imp":"Moderate to severe croup","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","o2":"O2 therapy: oxygen as needed, nasal cannula or face mask with flow by age and weight","sc":"کودک ۱۸ ماهه با استریدور در استراحت، retraction و SpO2 91٪.","why":"epinephrine نبولایز به‌علاوه استروئید؛ بستری اگر مداوم یا > 2 نوبت."}],"ch":"69","name":"Viral croup (laryngotracheobronchitis)","name_fa":"کروپ ویروسی (لارنگوتراکئوبرونکیت)","cc":["pediatric-respiratory"],"keywords":"croup, stridor, barking cough, steeple sign, dexamethasone, racemic epinephrine, budesonide, heliox, کروپ","status":"draft","features":["شایع‌ترین علت استریدور بعد از دوره نوزادی؛ خوش‌خیم و خودمحدود؛ ادم و التهاب ساب‌گلوتیک؛ پاییز و اوایل زمستان؛ 6 ماه تا 3 سال با اوج 12 تا 24 ماه","پرودروم 1 تا 3 روز سرفه، آبریزش و تب خفیف؛ سپس 3 تا 4 روز سرفه پارس‌دار؛ اوج روز 3 تا 4 و شبانه بدتر؛ استریدور با جزء دمی بیشتر؛ شدید: استریدور در استراحت، تاکی‌پنه، nasal flaring و retraction","تشخیص بالینی؛ رادیوگرافی لازم نیست مگر برای علل دیگر؛ steeple sign نه حساس نه اختصاصی","افتراق: اپی‌گلوتیت، تراکئیت باکتریال، آسپیراسیون جسم خارجی"],"ddx":[{"n":"Epiglottitis |","cm":1},{"n":"Bacterial tracheitis |","cm":1},{"n":"Airway foreign body |","cm":1},{"n":"Retropharyngeal abscess |"},{"n":"Angioedema |"}],"redflags":["استریدور در استراحت، retraction، هیپوکسی، بیمار سمی (فکر به اپی‌گلوتیت/تراکئیت)"],"guide":"بیمار با استریدور قابل‌توجه: در وضعیت راحت با حداقل تحریک؛ پالس‌اکسیمتری و اکسیژن در صورت نیاز. dexamethasone 0.15 تا 0.6 mg/kg (حداکثر 10 mg) PO یا IM (فرمول IV را می‌توان خوراکی داد)؛ budesonide نبولایز 2 mg اگر خوراکی تحمل نشود؛ حتی خفیف از استروئید سود می‌برد (یک دوز). racemic epinephrine 2.25٪ نبولایز 0.05 mL/kg/dose تا 0.5 mL برای متوسط تا شدید (استریدور در استراحت)؛ یا L-epinephrine (1:1000) 0.5 mL/kg/dose تا 5 mL؛ استریدور فقط با آژیتاسیون نیاز به epinephrine ندارد. اینتوباسیون در صورت اندیکاسیون (لوله کوچک‌تر از تخمین سنی)؛ heliox (70/30) فایده قطعی ندارد. بستری: استریدور در استراحت، تاکی‌پنه، retraction یا هیپوکسی یا > 2 نوبت epinephrine. ترخیص: ≥ 3 ساعت از آخرین epinephrine، ظاهر غیرسمی، بدون دهیدراتاسیون، SpO2 هوای اتاق > 90٪، توانایی والدین در تشخیص تغییر و دسترسی به تلفن و زمان کوتاه انتقال.","pearls":["چگال‌ترین خطر: اگر بیمار سمی است به اپی‌گلوتیت یا تراکئیت باکتریال فکر کن."],"section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 69: Upper Respiratory Emergencies—Stridor and Drooling Christopher S. Cavagnaro, pp. 372–378"},"epiglottitis":{"id":"epiglottitis","variants":[{"id":"epiglottitis-main","o":{"I":[{"t":"Lateral neck films at the bedside in extension during inspiration with minimum disturbance (only if diagnosis uncertain; physician trained in airway management must accompany)"}],"L":[{"t":"Blood cultures (positive in up to 90%)"}],"A":[{"t":"Cefuroxime 50 mg/kg/dose IV, or Cefotaxime 50 mg/kg/dose IV, or Ceftriaxone 50 mg/kg/dose IV; add Vancomycin 10 mg/kg/dose IV in regions with increased cephalosporin resistance"}],"T":[{"t":"Nebulized racemic or L-epinephrine; heliox can also be attempted"},{"t":"Methylprednisolone 2 mg/kg IV or Dexamethasone 0.15 to 0.6 mg/kg IV (decrease mucosal edema)"},{"t":"Bag-valve-mask ventilation if total airway loss; intubation by the most experienced individual as soon as the diagnosis is made (sedation, paralytics, vagolytics as indicated; multiple endotracheal tube sizes available; surgical airway ready)"}],"Co":[{"t":"Alert referral center or pediatric otolaryngologist or anesthesiologist for definitive airway management"}]},"name":"Epiglottitis","level":"I","imp":"Epiglottitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","o2":"O2 therapy: oxygen with the patient kept seated and upright, minimal disturbance","sc":"کودک ۵ ساله با تب 40، ترشح بزاق، صدای خفه و وضعیت tripod.","why":"راه هوایی مقدم است؛ بیمار را دستکاری نکن؛ اینتوباسیون توسط باتجربه‌ترین فرد."}],"ch":"69","name":"Epiglottitis (supraglottitis)","name_fa":"اپی‌گلوتیت (سوپراگلوتیت)","cc":["pediatric-respiratory","ent"],"keywords":"epiglottitis, supraglottitis, thumb sign, tripod position, drooling, cefuroxime, ceftriaxone, اپی‌گلوتیت","status":"draft","features":["تهدیدکننده حیات در هر سنی؛ قبلاً Hib (کاهش با واکسن)؛ در ایمن‌شده‌ها استرپتوکوک و استافیلوکوک؛ کاندیدا در ایمنوساپرس","شروع ناگهانی تب بالا، گلودرد و ترشح بزاق؛ پیشرفت سریع به استریدور و دیسترس؛ سرفه ممکن است نباشد، صدا خفه؛ بیمار سمی با وضعیت tripod یا sniffing","بزرگ‌ترها: گلودرد شدید، اوروفارنکس طبیعی، تندرنس شدید با حرکت ملایم هیوئید","رادیوگرافی لاترال گردن (در صورت شک) کنار تخت در اکستانسیون حین دم؛ «thumb sign»؛ منفی کاذب ممکن؛ کشت خون تا 90٪ مثبت"],"ddx":[{"n":"Epiglottitis |","cm":1},{"n":"Bacterial tracheitis |","cm":1},{"n":"Viral croup |"},{"n":"Retropharyngeal / peritonsillar abscess |"},{"n":"Airway foreign body |"}],"redflags":["ترشح بزاق، tripod/sniffing، ظاهر سمی، استریدور"],"guide":"بیمار نشسته و راست؛ اکسیژن؛ racemic یا L-epinephrine نبولایز؛ heliox قابل تلاش. اگر راه هوایی کاملاً از دست رفت: BVM. هماهنگی با مرکز ارجاع/ENT/بیهوشی اطفال؛ باتجربه‌ترین فرد به‌محض تشخیص اینتوبه کند؛ سداتیو، فلج‌کننده و واگولیتیک در صورت لزوم؛ اندازه‌های متعدد لوله آماده؛ در بیمار با راه هوایی حفظ‌شده، فلج‌کننده فقط با اطمینان از موفقیت یا راه هوایی جراحی فوری. استروئید: methylprednisolone 2 mg/kg IV یا dexamethasone 0.15 تا 0.6 mg/kg IV. آنتی‌بیوتیک: cefuroxime 50 mg/kg/dose IV، cefotaxime 50 mg/kg/dose IV یا ceftriaxone 50 mg/kg/dose IV؛ در مقاومت سفالوسپورین vancomycin 10 mg/kg/dose IV اضافه.","pearls":["بیمار را به رادیولوژی نبر مگر با پزشک آموزش‌دیده راه هوایی."],"section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 69: Upper Respiratory Emergencies—Stridor and Drooling Christopher S. Cavagnaro, pp. 372–378"},"bacterial-tracheitis":{"id":"bacterial-tracheitis","variants":[{"id":"tracheitis-main","o":{"I":[{"t":"Lateral neck and chest radiographs (subglottic narrowing with irregular densities); bronchoscopy most diagnostic"}],"A":[{"t":"Ampicillin/sulbactam 50 mg/kg/dose IV, or Ceftriaxone 50 mg/kg/dose IV plus Clindamycin 10 mg/kg/dose IV; consider Vancomycin 10 mg/kg/dose IV where S. aureus resistance is increasing"}],"T":[{"t":"Airway management as for epiglottitis; frequently requires intubation (ideally in the operating room with bronchoscopy for cultures and Gram stain)"}],"Co":[{"t":"Admit; otolaryngology / anesthesia"}]},"name":"Bacterial tracheitis","level":"I","imp":"Bacterial tracheitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"portable","o2":"O2 therapy: oxygen as needed with airway management as for epiglottitis","sc":"کودک ۶ ساله بدحال با تب، استریدور و خلط غلیظ بعد از سرماخوردگی.","why":"نیاز به اینتوباسیون و برونکوسکوپی؛ آنتی‌بیوتیک وریدی."}],"ch":"69","name":"Bacterial tracheitis","name_fa":"تراکئیت باکتریال","cc":["pediatric-respiratory"],"keywords":"bacterial tracheitis, bacterial croup, membranous laryngotracheobronchitis, ampicillin sulbactam, clindamycin, تراکئیت","status":"draft","features":["غیرشایع؛ اولیه یا ثانویه؛ میانگین سنی 5 تا 8 سال؛ S. aureus، S. pneumoniae و گرم‌منفی تولیدکننده β-lactamase (H. influenzae، M. catarrhalis)","بیمار سمی با دیسترس بیشتر از کروپ؛ بدتر شدن ناگهانی عفونت تنفسی فوقانی با تب، گلودرد، استریدور و سرفه گاهی خلط غلیظ","رادیوگرافی لاترال: تنگی ساب‌گلوتیک با تراکئای نامنظم؛ برونکوسکوپی تشخیصی‌ترین"],"ddx":[{"n":"Epiglottitis |","cm":1},{"n":"Viral croup |"},{"n":"Airway foreign body |"}],"redflags":["ظاهر سمی، دیسترس تنفسی شدید"],"guide":"مدیریت راه هوایی مثل اپی‌گلوتیت؛ اغلب نیاز به اینتوباسیون؛ ایده‌آل: اینتوباسیون و برونکوسکوپی در اتاق عمل با Gram و کشت. آنتی‌بیوتیک: ampicillin/sulbactam 50 mg/kg/dose IV یا ceftriaxone 50 mg/kg/dose IV + clindamycin 10 mg/kg/dose IV؛ در مقاومت S. aureus vancomycin 10 mg/kg/dose IV.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 69: Upper Respiratory Emergencies—Stridor and Drooling Christopher S. Cavagnaro, pp. 372–378"},"airway-foreign-body-peds":{"id":"airway-foreign-body-peds","variants":[{"id":"fb-airway-complete","o":{"T":[{"t":"Basic life support procedures to relieve airway obstruction (see Chapter 3)"},{"t":"If BLS fails: direct laryngoscopy and extraction with Magill forceps; if not seen, orotracheal intubation with dislodgement of the foreign body distally may be lifesaving"},{"t":"If obstructive laryngotracheal foreign body cannot be removed or dislodged: emergent surgical airway"}],"Co":[{"t":"Otolaryngology / pediatric surgery for rigid bronchoscopy"}]},"name":"Complete airway obstruction by foreign body","level":"I","imp":"Airway foreign body with obstruction","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","o2":"O2 therapy: oxygen as available; basic life support to relieve obstruction first","sc":"کودک ۲ ساله با خفگی ناگهانی هنگام خوردن بادام‌زمینی، سیانوز و ناتوانی در گریه.","why":"BLS، سپس لارنگوسکوپی و Magill؛ در شکست راه هوایی جراحی."},{"id":"fb-airway-partial","o":{"I":[{"t":"Inspiratory and expiratory posteroanterior chest radiographs in a stable cooperative child; decubitus films in a stable noncooperative child (less sensitive than fluoroscopy); radiographs may be normal"}],"Co":[{"t":"Rigid bronchoscopy in the operating room under general anesthesia (definitive treatment of partial airway obstruction; indicated if clinically suspected)"}]},"name":"Suspected foreign body aspiration, stable","level":"II","imp":"Suspected airway foreign body aspiration","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"PA","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"کودک ۲ ساله با سرفه ناگهانی دیروز و ویز یک‌طرفه؛ پایدار.","why":"شک بالینی نیاز به برونکوسکوپی دارد؛ CXR دمی و بازدمی."}],"ch":"69","name":"Airway foreign body in children","name_fa":"جسم خارجی راه هوایی در کودکان","cc":["pediatric-respiratory","airway-procedure"],"keywords":"foreign body aspiration, choking, unilateral wheeze, bronchoscopy, Magill forceps, decubitus films, آسپیراسیون جسم خارجی","status":"draft","features":["> 3000 مرگ در سال؛ اوج 1 تا 3 سال؛ زیر 6 ماه معمولاً تغذیه توسط خواهر/برادر","غذا (بادام‌زمینی، تخمه، کشمش، انگور، هات‌داگ) و اسباب‌بازی؛ مواد گیاهی پنومونیت شدید و عفونت ریوی؛ شک: شروع ناگهانی سرفه یا خفگی و هر کودک با ویز یک‌طرفه","بسیاری بدون علامت؛ سرفه ناگهانی با gagging، خفگی، استریدور یا سیانوز؛ حنجره-نای: استریدور و گرفتگی صدا؛ برونش: ویز یک‌طرفه و کاهش صدای تنفس؛ 80٪ تا 90٪ در برونش؛ علائم در تعیین سطح غیرقابل اتکا","CXR می‌تواند در > 50٪ FB نای و 25٪ FB برونش طبیعی باشد؛ > 75٪ FB در < 3 سال رادیولوسنت؛ انسداد کامل: آتلکتازی؛ جزئی: air trapping با hyperinflation در بازدم؛ کودک همکار: CXR دمی و بازدمی؛ ناهمکار: decubitus (کمتر از فلوروسکوپی)؛ تشخیص پیش از عمل فقط در یک‌سوم: در شک بالینی برونکوسکوپی","FB مری فوقانی معمولاً رادیواپک؛ سکه در نای در صفحه ساژیتال و در مری در صفحه کرونال"],"ddx":[{"n":"Complete airway obstruction |","cm":1},{"n":"Asthma / bronchiolitis / pneumonia |"},{"n":"Croup |"},{"n":"Esophageal foreign body |"}],"redflags":["استریدور ناگهانی شدید، سیانوز، ایست قلبی، ویز یک‌طرفه"],"guide":"انسداد واضح: BLS برای رفع انسداد (فصل ۳)؛ شکست: لارنگوسکوپی مستقیم و خارج کردن با Magill forceps؛ اگر دیده نشد: اینتوباسیون اوروتراکئال و جابه‌جایی FB به دیستال ممکن است نجات‌بخش باشد؛ در انسداد غیرقابل رفع: راه هوایی جراحی اورژانس. درمان قطعی انسداد جزئی: برونکوسکوپی سخت در اتاق عمل زیر بیهوشی عمومی.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 69: Upper Respiratory Emergencies—Stridor and Drooling Christopher S. Cavagnaro, pp. 372–378"},"retropharyngeal-peritonsillar-abscess":{"id":"retropharyngeal-peritonsillar-abscess","variants":[{"id":"retropharyngeal-abscess","o":{"I":[{"t":"Lateral neck radiograph during inspiration (retropharyngeal space at C2 twice the diameter of the vertebral body or greater than one half the width of C4); CT of the neck with IV contrast (define extent, cellulitis vs abscess)"}],"A":[{"t":"Ampicillin/sulbactam 50 mg/kg/dose IV, or Clindamycin 10 mg/kg/dose IV; Ceftriaxone 50 mg/kg/dose IV in the penicillin-allergic patient"}],"T":[{"t":"Dexamethasone 0.15 to 0.6 mg/kg IV (maximum 10 mg) (adjunct to reduce inflammation and edema)"},{"t":"Immediate airway stabilization; intubate unstable patients before performing CT","fl":[{"k":"ci","v":"do not palpate the abscess (rupture)"}]}],"Co":[{"t":"Otolaryngology consult for operative incision and drainage (retropharyngeal cellulitis and very small abscesses may improve with antibiotics alone)"}]},"name":"Retropharyngeal abscess","level":"I","imp":"Retropharyngeal abscess","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","o2":"O2 therapy: oxygen as needed; airway stabilization first","sc":"کودک ۲ ساله با تب، ترشح بزاق، دیسفاژی و torticollis.","why":"فضای رتروفارنژیال فقط در کودکان کوچک؛ اولویت راه هوایی؛ CT با کنتراست."},{"id":"peritonsillar-abscess","o":{"I":[{"t":"CT with contrast or ultrasound only if toxic appearance or atypical exam findings"}],"S":[{"t":"Empiric IV fluid boluses (patients may be dehydrated on presentation or not drink well after drainage)","fl":[{"k":"note","v":"volume not given in the book"}]}],"A":[{"t":"Clindamycin 10 mg/kg/dose IV, or Ampicillin/sulbactam 50 mg/kg/dose IV; outpatient oral: Amoxicillin/clavulanate 45 mg/kg/dose twice daily, or Clindamycin 10 mg/kg/dose every eight hours"}],"T":[{"t":"Topical (benzocaine or endocaine spray), oral (oxycodone or Vicodin) or parenteral (fentanyl, morphine) analgesia, then needle aspiration of the abscess with a large gauge needle, avoiding deep penetration","fl":[{"k":"hi","v":""}]}],"Co":[{"t":"Definitive follow-up essential in all cases; operating room incision and drainage sometimes necessary (young or uncooperative patients)"}]},"name":"Peritonsillar abscess","level":"II","imp":"Peritonsillar abscess","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"نوجوان ۱۷ ساله با گلودرد، تب، trismus، صدای «hot potato» و انحراف uvula.","why":"آسپیراسیون با سوزن، آنتی‌بیوتیک و مسکن؛ پیگیری قطعی."}],"ch":"69","name":"Retropharyngeal and peritonsillar abscess","name_fa":"آبسه رتروفارنژیال و پری‌تانسیلار","cc":["pediatric-respiratory","ent","pediatric-fever"],"keywords":"retropharyngeal abscess, peritonsillar abscess, quinsy, trismus, hot potato voice, needle aspiration, clindamycin, ampicillin sulbactam, آبسه پری‌تانسیلار","status":"draft","features":["رتروفارنژیال: فضای بالقوه فقط در کودکان خردسال (< 4 سال)؛ تب، ترشح بزاق، دیسفاژی ± استریدور دمی؛ وضعیت غیرعادی گردن (torticollis، هایپراکستانسیون، سفتی)؛ عوارض: انسداد راه هوایی با پارگی ناگهانی، پنومونی آسپیراسیون، آمپیم، مدیاستینیت، فرسایش ورید ژوگولار و کاروتید","معاینه: توده رتروفارنژیال؛ لمس باعث پارگی می‌شود؛ لاترال گردن دمی: فضای C2 ≥ 2 برابر عرض جسم مهره یا > نصف عرض C4؛ CT گردن با کنتراست برای وسعت و افتراق سلولیت از آبسه","پری‌تانسیلار: معمولاً یک‌طرفه، عفونت عمقی پلی‌میکروبیال؛ نوجوانان و بزرگسالان جوان؛ گلودرد، تب، لرز، دیسفاژی/ادینوفاژی، trismus، ترشح بزاق و صدای «hot potato»؛ انحراف uvula از سمت درگیر، جابه‌جایی قدامی-داخلی لوزه","تصویربرداری معمولاً لازم نیست؛ در بیمار سمی یا معاینه آتیپیک: CT با کنتراست یا سونوگرافی"],"ddx":[{"n":"Epiglottitis |","cm":1},{"n":"Retropharyngeal abscess with airway compromise |","cm":1},{"n":"Peritonsillar cellulitis |"},{"n":"Mediastinitis / jugular vein involvement |"},{"n":"Ludwig angina |"}],"redflags":["استریدور، trismus، ترشح بزاق، نمای سمی، راه هوایی تهدیدشده"],"guide":"# رتروفارنژیال\nاولویت: تثبیت راه هوایی؛ ناپایدار را قبل از CT اینتوبه کن. آنتی‌بیوتیک (بحث‌برانگیز؛ فلور مخلوط): ampicillin/sulbactam 50 mg/kg/dose IV یا clindamycin 10 mg/kg/dose IV؛ آلرژی پنی‌سیلین: ceftriaxone 50 mg/kg/dose IV به‌جای ampicillin/sulbactam. استروئید کمکی: dexamethasone 0.15 تا 0.6 mg/kg IV (حداکثر 10 mg). سلولیت و آبسه‌های کوچک ممکن است فقط با آنتی‌بیوتیک بهتر شوند؛ بیشتر نیاز به برش و درناژ ENT.\n# پری‌تانسیلار\nبیشتر موارد: آسپیراسیون با سوزن، آنتی‌بیوتیک و کنترل درد: بی‌حسی موضعی (benzocaine یا endocaine اسپری)، خوراکی (oxycodone یا Vicodin) یا تزریقی (fentanyl، morphine)، سپس آسپیراسیون با سوزن بزرگ؛ از نفوذ عمیق (آسیب عروق) بپرهیز (کوتاه کردن سوزن با محافظ). clindamycin 10 mg/kg/dose IV یا ampicillin/sulbactam 50 mg/kg/dose IV؛ سرپایی: amoxicillin/clavulanate 45 mg/kg/dose دو بار روزانه یا clindamycin 10 mg/kg/dose هر 8 ساعت؛ پیگیری قطعی ضروری؛ گاهی I&D در اتاق عمل (کودک یا ناهمکار)؛ بولوس مایع وریدی (دهیدراتاسیون).","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 69: Upper Respiratory Emergencies—Stridor and Drooling Christopher S. Cavagnaro, pp. 372–378"},"asthma-peds":{"id":"asthma-peds","variants":[{"id":"asthma-peds-mild-moderate","o":{"I":[{"t":"Chest radiography only if failure to improve as expected, fever, concern for pneumothorax or foreign body (unilateral wheezing), or focal lung findings"}],"T":[{"t":"Albuterol by metered-dose inhaler with spacer 4 to 8 puffs every 20 minutes up to three doses, or nebulization 2.5 to 5 mg every 20 minutes up to three doses"},{"t":"Ipratropium with albuterol 0.25 to 0.5 mg every 20 minutes × 3 doses (superior in severe asthma)"},{"t":"Prednisone or prednisolone 2 mg/kg/dose (maximum 60 mg/dose), or Dexamethasone 0.6 mg/kg (maximum 10 to 16 mg)","fl":[{"k":"note","v":"not needed in the most mildly ill who respond immediately to albuterol"}]}],"Co":[{"t":"Observe 2 to 3 hours after albuterol (sicker on arrival); discharge with an asthma action plan, albuterol as MDI or nebulizer, oral corticosteroids and primary care follow-up"}]},"name":"Mild to moderate asthma exacerbation","level":"III","imp":"Pediatric asthma exacerbation (mild to moderate)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: oxygen for saturations below 92%; nasal cannula or face mask with flow by age and weight","sc":"پسر ۶ ساله با ویز و سرفه، retraction خفیف و SpO2 94٪.","why":"آلبوترول تکراری، استروئید زودهنگام و ارزیابی سریال."},{"id":"asthma-peds-severe","o":{"I":[{"t":"Chest radiography if concern for pneumothorax (pain or significant hypoxia) or foreign body"}],"S":[{"t":"Normal saline IV fluids for status asthmaticus with decreased oral intake or NPO"},{"t":"IV fluid bolus of 20 cc/kg before magnesium sulfate to avoid decline in blood pressure","fl":[{"k":"ci","v":"caution in heart failure"}]}],"T":[{"t":"Continuously nebulized albuterol 0.5 mg/kg/h; Ipratropium 0.25 to 0.5 mg every 20 minutes × 3 doses concurrently"},{"t":"Methylprednisolone IV 1 mg/kg/dose"},{"t":"Magnesium sulfate 50 to 75 mg/kg (maximum 2 g) IV over 10 to 20 minutes for poor ventilation"},{"t":"Terbutaline SQ or IM 0.01 mg/kg (maximum 0.4 mg) every 20 minutes × 3 doses if no IV access; or Epinephrine SQ or IM 0.01 mg/kg (maximum 0.5 mg) every 15 minutes"},{"t":"Critically ill nearing intubation: Ketamine 2 mg/kg IV followed by 2 to 3 mg/kg/h; or Heliox 60:40 or 70:30 (maximum FiO2 40%) with nebulized albuterol"},{"t":"Noninvasive ventilation (BiPAP); if intubation required: atropine 0.02 mg/kg (minimum 0.5 mg, maximum 1 mg) and lidocaine 1.5 mg/kg premedication, ketamine 2 mg/kg, then succinylcholine 2 mg/kg or rocuronium 1 mg/kg; permissive hypercapnia"}],"Co":[{"t":"Admit (PICU if ventilatory failure); persistent hypoxemia or albuterol needed at least every 2 hours"}]},"name":"Severe asthma exacerbation / status asthmaticus","level":"I","imp":"Pediatric status asthmaticus","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","o2":"O2 therapy: oxygen to keep SpO2 ≥ 92%; nasal cannula or face mask with flow by age and weight; monitor ETCO2 by capnometry","sc":"دختر ۷ ساله با ویز شدید، retraction، قادر به گفتن چند کلمه و SpO2 88٪.","why":"شدید: آلبوترول مداوم، ipratropium، استروئید وریدی، منیزیم؛ ETCO2 نرمال = هشدار."}],"ch":"70","name":"Pediatric asthma exacerbation","name_fa":"حمله آسم در کودکان","cc":["pediatric-respiratory","dyspnea"],"keywords":"pediatric asthma, wheezing child, albuterol, ipratropium, prednisone, dexamethasone, magnesium sulfate, terbutaline, heliox, ketamine, status asthmaticus, آسم کودکان","status":"draft","features":["شایع‌ترین بیماری مزمن کودکی و شایع‌ترین علت بستری کودکان؛ التهاب راه هوایی با ویز راجعه، تنگی نفس و سرفه با انسداد بازگشت‌پذیر؛ محرک‌ها: عفونت ویروسی، آلرژن، ورزش، محرک‌های محیطی (دود سیگار، هوای سرد)","ویز: علامت شاخص؛ سرفه، تنگی نفس، تنگی یا درد سینه؛ شدت (خفیف/متوسط/شدید) با ویز، تعداد تنفس، کار تنفسی (retraction، nasal flaring)، کیفیت aeration و نسبت دم/بازدم","ارزیابی‌های سریال کلیدی است؛ تغییر وضعیت و پاسخ به درمان مهم‌تر از شدت اولیه","هیپوکسمی معمولاً خفیف (SpO2 > 92٪) و V/Q mismatch؛ ممکن است 1 تا 2 ساعت بعد از برونکودیلاتور بدتر شود؛ ETCO2: هیپوکاپنی اولیه، ETCO2 نرمال یا کمی بالا = نارسایی تنفسی قریب‌الوقوع","> 2 سال بدون سابقه: تشخیص موقت آسم با ویز و برگشت‌پذیری با β2-agonist؛ < 2 سال بدون سابقه فردی/خانوادگی در همه‌گیری ویروسی: برونشیولیت","CXR: عدم بهبودی مورد انتظار، تب، شک پنوموتوراکس (درد یا هیپوکسی شدید) یا جسم خارجی (ویز یک‌طرفه)، یافته کانونی"],"ddx":[{"n":"Airway foreign body (unilateral wheeze) |","cm":1},{"n":"Pneumothorax |","cm":1},{"n":"Bronchiolitis |"},{"n":"Pneumonia |"},{"n":"Anaphylaxis / vocal cord dysfunction |"},{"n":"Congenital heart disease / heart failure |"}],"redflags":["ETCO2 نرمال یا بالا، خستگی، هیپوکسی پایدار، سینه ساکت، نیاز به albuterol هر < 2 ساعت"],"guide":"# درمان\n- اکسیژن برای SpO2 < 92٪.\n- albuterol: MDI با spacer 4 تا 8 puff هر 20 دقیقه تا 3 دوز یا نبولایزر 2.5 تا 5 mg هر 20 دقیقه تا 3 دوز (معادل)؛ شدید: نبولایز مداوم 0.5 mg/kg/h؛ ipratropium همراه albuterol در شدید برتر: 0.25 تا 0.5 mg هر 20 دقیقه × 3؛ levalbuterol برتری ندارد.\n- استروئید سیستمیک در همه به‌جز خفیف با پاسخ فوری (ترجیحاً از تریاژ): prednisone/prednisolone 2 mg/kg/dose حداکثر 60 mg یا dexamethasone 0.6 mg/kg حداکثر 10 تا 16 mg؛ شدید: methylprednisolone IV 1 mg/kg/dose.\n- β-agonist سیستمیک فقط در تهویه ضعیف و عدم رسیدن دارو: terbutaline SQ/IM 0.01 mg/kg حداکثر 0.4 mg هر 20 دقیقه × 3؛ epinephrine SQ/IM 0.01 mg/kg حداکثر 0.5 mg هر 15 دقیقه.\n- منیزیم سولفات 50 تا 75 mg/kg حداکثر 2 g IV طی 10 تا 20 دقیقه در تهویه ضعیف؛ قبل از آن بولوس مایع 20 cc/kg.\n- بیمار بحرانی نزدیک به اینتوباسیون: ketamine 2 mg/kg IV سپس 2 تا 3 mg/kg/h یا heliox (60:40 یا 70:30؛ حداکثر FiO2 40٪).\n- مایع وریدی (نرمال سالین) در status asthmaticus با کاهش دریافت یا NPO.\n- اینتوباسیون نادر (بارتروما، لارنگواسپاسم)؛ BiPAP؛ باتجربه‌ترین؛ RSI: atropine 0.02 mg/kg (حداقل 0.5، حداکثر 1 mg) و lidocaine 1.5 mg/kg، ketamine 2 mg/kg، سپس succinylcholine 2 mg/kg یا rocuronium 1 mg/kg؛ permissive hypercapnia.\n# دیسپوزیشن\nمشاهده 2 تا 3 ساعت بعد از albuterol در بدحال‌تر؛ بستری: پاسخ ناکافی، هیپوکسمی، تاکی‌پنه، نیاز به albuterol هر ≤ 2 ساعت، یا مراقبت ناکافی؛ ترخیص: action plan، albuterol، استروئید خوراکی و پیگیری.\n# دوزهای جدول 70-1\nalbuterol MDI (90 μg/puff): ≤ 1 سال 2 puff، 1–3 سال 4 puff، ≥ 4 سال 8 puff؛ نبولایزر 0.15–0.3 mg/kg/dose (حداقل 2.5 mg)؛ methylprednisolone IV/IM: 2 mg/kg بار سپس 0.5–1 mg/kg هر 6 ساعت؛ dexamethasone 0.6 mg/kg/dose (حداکثر 16 mg) 1 تا 2 روز.","pearls":["ETCO2 نرمال در آسم شدید می‌تواند علامت نارسایی تهویه باشد."],"section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 70: Wheezing in Infants and Children, pp. 379–384"},"bronchiolitis":{"id":"bronchiolitis","variants":[{"id":"bronchiolitis-mild","o":{"T":[{"t":"Nasal suctioning after saline drops (deep suctioning decreases work of breathing, corrects hypoxemia and enables normal feeding)","fl":[{"k":"ci","v":"nasal vasoconstrictors not indicated (tachydysrhythmias)"}]}],"Co":[{"t":"Follow-up; return for persistent hypoxia, significant tachypnea or work of breathing, inability to feed or maintain hydration"}]},"name":"Mild bronchiolitis, well hydrated","level":"III","imp":"Bronchiolitis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: only to maintain saturations > 90%; nasal cannula with flow by age and weight","sc":"شیرخوار ۸ ماهه با آبریزش، سرفه و ویز؛ تغذیه خوب.","why":"خفیف و هیدراته: فقط ساکشن بینی."},{"id":"bronchiolitis-moderate-severe","o":{"I":[{"t":"Chest radiograph only if other diseases or foreign body aspiration suspected, or severe disease"}],"S":[{"t":"Isotonic IV fluids (normal saline) if necessary (cannot feed normally; RR > 60 to 70 increases aspiration risk)"}],"T":[{"t":"Nasal suctioning and saline drops"},{"t":"Heated, humidified high-flow nasal cannula therapy for moderately to severely ill infants; CPAP or BiPAP if needed (may prevent further apnea)"},{"t":"Albuterol may be considered for a moderately ill infant (especially with personal or family history of asthma or atopy); nebulized Epinephrine 0.5 mL of 1:1000 in 2.5 mL saline for hospitalized patients with suboptimal response to β2-agonists; stop if no objective response"},{"t":"Nebulized hypertonic saline 3% or 5%, 3 to 5 mL for hospitalized infants unresponsive to other interventions","fl":[{"k":"ci","v":"no routine corticosteroids"}]}],"Co":[{"t":"Admit (persistent hypoxia, significant tachypnea or work of breathing, inability to feed; risk factors for apnea and severe disease)"}]},"name":"Moderate to severe bronchiolitis (hospitalization)","level":"II","imp":"Bronchiolitis (moderate to severe)","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","o2":"O2 therapy: oxygen to maintain saturations > 90%; heated humidified high-flow nasal cannula (HFNC) up to 12 L/min in infants","sc":"شیرخوار ۲ ماهه نارس با تاکی‌پنه 70، retraction، SpO2 88٪ و عدم تغذیه.","why":"نیاز به اکسیژن/HFNC و مایع؛ خطر آپنه؛ بستری."}],"ch":"70","name":"Bronchiolitis in infants","name_fa":"برونشیولیت شیرخواران","cc":["pediatric-respiratory","dyspnea"],"keywords":"bronchiolitis, RSV, nasal suctioning, high-flow nasal cannula, hypertonic saline, apnea, برونشیولیت","status":"draft","features":["شایع‌ترین عفونت تنفسی تحتانی در 2 سال اول؛ معمولاً RSV؛ التهاب و ادم راه هوایی، نکروز اپیتلیوم، مخاط زیاد و برونکواسپاسم","ویز و آبریزش (URI) با تب، تاکی‌پنه، سرفه، رال، عضلات فرعی و nasal flaring؛ آپنه و دهیدراتاسیون نگران‌کننده (< 3 ماه یا نارس)؛ هیپوکسمی، سیانوز، تغییر هوشیاری و خستگی: نارسایی تنفسی","شدت در 3 تا 5 روز اول افزایش می‌یابد؛ مدت کل 7 تا 14 روز","برخلاف آسم اغلب به β-agonist و استروئید پاسخ نمی‌دهد؛ < 2 سال (اوج 6 تا 12 ماه)، بدون سابقه فردی/خانوادگی ویز یا آتوپی، URI و همه‌گیری ویروسی؛ تشخیص بالینی؛ تست RSV و CXR روتین لازم نیست","CXR فقط در شک بیماری دیگر یا جسم خارجی یا بیماری شدید"],"ddx":[{"n":"Apnea |","cm":1},{"n":"Pneumonia / airway foreign body |","cm":1},{"n":"Asthma |"},{"n":"Congenital heart disease / heart failure |"},{"n":"Pertussis |"}],"redflags":["آپنه، هیپوکسمی پایدار، سیانوز، تغییر هوشیاری، تاکی‌پنه > 60 تا 70"],"guide":"ساکشن عمیق بینی بعد از قطره سالین (کاهش کار تنفس، اصلاح هیپوکسمی و امکان تغذیه)؛ وازوکانستریکتور بینی ممنوع (تاکی‌دیس‌ریتمی)؛ خفیف و هیدراته: فقط ساکشن. اکسیژن برای SpO2 > 90٪؛ HFNC گرم و مرطوب تا 12 L/min شیرخوار (شبیه CPAP) برای همه متوسط تا شدید. نبولایز α/β-agonist روتین نه؛ albuterol در متوسط به‌ویژه با سابقه آسم/آتوپی؛ epinephrine نبولایز 0.5 mL از 1:1000 در 2.5 mL سالین برای بستری با پاسخ ضعیف به β2؛ ارزیابی عینی پاسخ (RR یا امتیاز برونشیولیت) و قطع در عدم پاسخ. سالین هایپرتونیک 3٪ یا 5٪ 3 تا 5 mL نبولایز برای بستری بدون پاسخ. مایع ایزوتونیک وریدی در صورت نیاز (RR > 60–70: خطر آسپیراسیون). استروئید روتین ممنوع. CPAP/BiPAP ممکن است آپنه را پیشگیری کند. بستری: هیپوکسی پایدار، تاکی‌پنه یا کار تنفسی قابل‌توجه، ناتوانی تغذیه/هیدراتاسیون؛ عوامل خطر: < 6 تا 12 هفته یا < 37 هفته، آپنه شاهدی، CHD مهم، بیماری مزمن ریه، نقص ایمنی.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 70: Wheezing in Infants and Children, pp. 379–384"},"pneumonia-peds":{"id":"pneumonia-peds","variants":[{"id":"pneumonia-peds-outpatient","o":{"L":[{"t":"No routine laboratory testing required for well-appearing children with mild community-acquired pneumonia; rapid viral antigen testing (RSV, influenza, human metapneumovirus) if quick and available"}],"A":[{"t":"3 months to 5 years: Amoxicillin with or without clavulanic acid, or Cefuroxime axetil; 5 to 18 years: Azithromycin (if M. pneumoniae suspected), or Amoxicillin with or without clavulanic acid, or Cefuroxime axetil","fl":[{"k":"note","v":"doses not given in the chapter; see Chapter 68 for weight-based amoxicillin dosing"}]}],"T":[{"t":"Antipyretics for febrile patients (may resolve tachypnea associated with fever); bronchodilators if wheezing","fl":[{"k":"note","v":"doses per Chapter 66 / Chapter 70"}]}],"Co":[{"t":"Outpatient follow-up; chest radiography reserved for questioned diagnosis or suspected complication"}]},"name":"Pneumonia in a well child (outpatient)","level":"III","imp":"Community-acquired pneumonia in a child","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if respiratory distress or SpO2 < 92% on room air, nasal cannula or face mask with flow by age and weight","sc":"دختر ۴ ساله با تب، سرفه و تاکی‌پنه 45؛ تغذیه خوب، SpO2 96٪.","why":"تشخیص بالینی؛ CXR لازم نیست؛ آموکسی‌سیلین سرپایی."},{"id":"pneumonia-peds-inpatient","o":{"I":[{"t":"Chest radiography (differential in question, complication suspected: failure of outpatient therapy, pleural effusion, cavitary pneumonia, comorbidity, age < 3 months)"}],"L":[{"t":"Blood culture, CBC and serum electrolytes (significant respiratory distress or toxic appearance); rapid viral antigen testing"}],"S":[{"t":"Dehydration: boluses of 20 mL/kg of normal saline","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]}],"A":[{"t":"3 months to 5 years inpatient: Ampicillin, or Ceftriaxone, or Cefotaxime, or Vancomycin, with or without a macrolide","fl":[{"k":"note","v":"doses not given in the chapter"}]}],"T":[{"t":"Antipyretics; bronchodilators if wheezing"}],"Co":[{"t":"Admit; PICU consultation for severe respiratory distress, impending respiratory failure or shock"}]},"name":"Pneumonia requiring admission (hypoxemia, dehydration, young infant)","level":"II","imp":"Pneumonia in a child requiring hospitalization","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"PA","o2":"O2 therapy: oxygen for respiratory distress or saturations less than 92% on room air; nasal cannula or face mask with flow by age and weight","sc":"شیرخوار ۸ ماهه با تب، تاکی‌پنه 65، retraction، SpO2 90٪ و کم‌خوری.","why":"هیپوکسمی و کم‌خوری: بستری با اکسیژن، مایع و آنتی‌بیوتیک وریدی."},{"id":"pneumonia-peds-neonate-young","o":{"I":[{"t":"Chest radiography (age < 3 months)"}],"L":[{"t":"Blood culture, CBC and serum electrolytes","fl":[{"k":"note","v":"full sepsis evaluation per Chapter 66 for neonates"}]}],"A":[{"t":"Neonates: Ampicillin plus Gentamicin or Cefotaxime","fl":[{"k":"note","v":"doses per Chapter 66: Ampicillin 50 mg/kg IV, Gentamicin 2.5 mg/kg IV or Cefotaxime 50 mg/kg IV"}]},{"t":"1 to 3 months: Ampicillin, or Ceftriaxone, or Cefotaxime, or Vancomycin; macrolide if C. trachomatis or B. pertussis suspected","fl":[{"k":"note","v":"doses not given in this chapter"}]}],"Co":[{"t":"Admit and monitor closely (outpatient treatment not indicated)"}]},"name":"Pneumonia in neonate or infant 1–3 months","level":"I","imp":"Pneumonia in neonate / young infant","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"portable","o2":"O2 therapy: oxygen for respiratory distress or saturations less than 92% on room air; nasal cannula or face mask with flow by age and weight","sc":"نوزاد ۲۰ روزه با تب، آپنه کوتاه و تاکی‌پنه 72.","why":"نوزاد: خطر دکمپانساسیون؛ بستری، آنتی‌بیوتیک وریدی؛ سپسیس ورک‌آپ."}],"ch":"71","name":"Pneumonia in infants and children","name_fa":"پنومونی در شیرخواران و کودکان","cc":["pediatric-respiratory","cough-hemoptysis","pediatric-fever"],"keywords":"pediatric pneumonia, community-acquired pneumonia, tachypnea, amoxicillin, ceftriaxone, azithromycin, Mycoplasma, RSV, پنومونی کودکان","status":"draft","features":["عفونت تحتانی راه تنفسی؛ از علل اصلی مرگ و میر کودکان؛ عامل وابسته به سن: نوزاد 0 تا 30 روز: GBS و گرم‌منفی روده‌ای (کلامیدیا در مراقبت پیش از زایمان ناکافی)؛ 1 ماه تا 2 سال: ویروس‌ها (RSV، انفلوانزا، پاراانفلوانزا، hMPV) و S. pneumoniae و H. influenzae؛ 2 تا 5 سال: ویروس‌ها سپس S. pneumoniae، H. influenzae و S. aureus؛ 5 تا 13 سال: Mycoplasma pneumoniae، S. pneumoniae، Chlamydophila؛ نوجوانان: مشابه بزرگسالان","بیشتر: تب، بیماری ویروسی قبلی، تاکی‌پنه، دیسترس تنفسی، رال و کاهش صدای تنفس؛ تاکی‌پنه حساس‌ترین یافته (جدول 71-1: 0–60 روز > 60؛ 2–12 ماه > 50؛ 1–5 سال > 40؛ > 5 سال > 20/min؛ شدید: > 70، > 60، > 50، > 50)","نوزاد/شیرخوار: علائم ظریف ولی ممکن است بدحال‌تر باشند (تب یا هیپوترمی، آپنه، تاکی‌پنه، خوردن ضعیف، استفراغ، بی‌حالی، grunting، شوک)؛ کودکان بزرگ‌تر: مشابه بزرگسال؛ کودکان کوچک با لوب تحتانی: درد شکم","تشخیص بالینی؛ CXR لازم نیست و استاندارد طلایی نیست؛ تب به‌علاوه تاکی‌پنه، کاهش صدا یا کراکل ریز: حساسیت 93٪ تا 96٪؛ با هر چهار: 98٪","CXR برای مشکوک به جسم خارجی، CHF، توده مدیاستن یا عارضه (شکست درمان سرپایی، پلورال افیوژن، حفره‌دار، بیماری زمینه‌ای مهم، سن < 3 ماه)","آزمایش روتین برای خفیف خوش‌ظاهر لازم نیست؛ نوزاد یا دیسترس شدید/بدحال: کشت خون، CBC و الکترولیت؛ تست سریع آنتی‌ژن ویروسی (RSV، انفلوانزا، hMPV) در صورت سریع"],"ddx":[{"n":"Sepsis / empyema / pleural effusion |","cm":1},{"n":"Airway foreign body |","cm":1},{"n":"Bronchiolitis / asthma |"},{"n":"Congestive heart failure / mediastinal mass |"},{"n":"Pertussis |"}],"redflags":["نوزاد، دیسترس تنفسی شدید یا نارسایی قریب‌الوقوع، شوک، هیپوکسی"],"guide":"مراقبت حمایتی: اکسیژن برای دیسترس یا SpO2 < 92٪ هوای اتاق؛ تب‌بر (ممکن است تاکی‌پنه ناشی از تب را برطرف کند)؛ برونکودیلاتور در ویز؛ دهیدراتاسیون با بولوس 20 mL/kg نرمال سالین. آنتی‌بیوتیک بر اساس سن و شدت (جدول 71-2): نوزاد: ampicillin + gentamicin یا cefotaxime (سرپایی نه)؛ 1 تا 3 ماه: ampicillin یا ceftriaxone یا cefotaxime یا vancomycin؛ ماکرولاید اگر C. trachomatis یا B. pertussis؛ 3 ماه تا 5 سال: سرپایی amoxicillin ± clavulanic acid یا cefuroxime axetil؛ بستری ampicillin یا ceftriaxone یا cefotaxime یا vancomycin ± ماکرولاید؛ 5 تا 18 سال: azithromycin (اگر M. pneumoniae) یا amoxicillin ± clavulanic acid یا cefuroxime؛ بستری مشابه. نوزاد: بستری و مانیتور. معیار بستری: کار تنفسی، هیپوکسمی، خوردن ضعیف، استفراغ مداوم، دهیدراتاسیون، عوامل اجتماعی؛ PICU: دیسترس شدید، نارسایی قریب‌الوقوع یا شوک.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 71: Pneumonia in Infants and Children, pp. 385–387"},"congenital-heart-cyanosis-shock":{"id":"congenital-heart-cyanosis-shock","variants":[{"id":"chd-cyanosis-neonate","o":{"I":[{"t":"Chest radiograph (heart size, shape, pulmonary blood flow, position of aortic arch); echocardiography (generally required to define the diagnosis)"}],"L":[{"t":"Preductal (right upper extremity) and postductal pulse oximetry and four-extremity blood pressures; hyperoxia test on 100% oxygen"}],"T":[{"t":"High-flow oxygen, cardiac and oxygen monitoring, and a stable intravenous or intraosseous line"},{"t":"Prostaglandin E1 0.05 µg/kg/min, tapered to the lowest effective dose; may be increased to 0.2 μg/kg/min if no improvement (fever, skin flushing, diarrhea, periodic apnea)","fl":[{"k":"hi","v":""}]}],"Co":[{"t":"Immediate pediatric cardiologist consultation; NICU/PICU admission"}]},"name":"Cyanotic neonate / suspected cyanotic heart disease","level":"I","imp":"Neonatal cyanosis (suspected congenital heart disease)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"O2 therapy: high-flow oxygen; hyperoxia test on 100% oxygen; note neonates tolerate low saturations; preductal and postductal pulse oximetry","sc":"نوزاد ۴ روزه با سیانوز مرکزی و تاکی‌پنه بدون زحمت؛ سوفل ندارد.","why":"hyperoxia test و ECG/CXR؛ اکو؛ PGE1 در شک به وابسته به داکتوس."},{"id":"chd-shock-neonate","o":{"I":[{"t":"Chest radiograph; ECG with pediatric analysis; echocardiography"}],"L":[{"t":"Four-extremity blood pressures (differential between preductal right brachial and postductal femoral pulses/BP); lactate","fl":[{"k":"note","v":"lactate not specified in this chapter"}]}],"S":[{"t":"Fluid challenge 10 to 20 mL/kg normal saline; in neonates with congenital heart disease more judiciously, typically 10 mL/kg boluses","fl":[{"k":"ci","v":"heart failure / pulmonary edema"}]}],"A":[{"t":"Empiric antibiotics as indicated for noncardiac causes (sepsis)","fl":[{"k":"note","v":"see Chapter 66"}]}],"T":[{"t":"Prostaglandin E1 0.05 µg/kg/min, tapered to the lowest effective dose; may increase to 0.2 μg/kg/min if no improvement","fl":[{"k":"hi","v":""}]},{"t":"Epinephrine infusion 0.05 to 0.5 μg/kg/min titrated to desired blood pressure (initial drug of choice for hypotension)"}],"Co":[{"t":"Immediate pediatric cardiologist and pediatric intensivist consultation; admit NICU/PICU"}]},"name":"Neonatal shock from ductal-dependent lesion (coarctation, critical AS, HLHS)","level":"I","imp":"Neonatal cardiogenic shock (ductal-dependent congenital heart disease)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"O2 therapy: oxygen cautiously (pulmonary steal may worsen systemic shock in ductal-dependent systemic flow); preductal and postductal oximetry","sc":"نوزاد ۱۰ روزه با رنگ خاکستری، نبض فمورال ضعیف، فشار پا کمتر از دست و اسیدوز لاکتیک.","why":"بستن داکتوس: PGE1 فوری؛ اکسیژن می‌تواند بدتر کند؛ بولوس‌های 10 mL/kg."},{"id":"chd-tet-spell","o":{"T":[{"t":"Knee-to-chest position; Morphine sulfate 0.2 mg/kg SC, IM or IO","fl":[{"k":"hi","v":""}]},{"t":"Resistant cases: Phenylephrine for hypotension or Propranolol for tachycardia, after immediate consultation with a pediatric cardiologist","fl":[{"k":"note","v":"doses not given in the book"}]}],"Co":[{"t":"Pediatric cardiologist consultation; admit"}]},"name":"Hypercyanotic (tet) spell of tetralogy of Fallot","level":"I","imp":"Hypercyanotic spell (tetralogy of Fallot)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","o2":"O2 therapy: high-flow oxygen with cardiac and oxygen monitoring","sc":"شیرخوار ۸ ماهه با TOF و سیانوز ناگهانی و سنکوپ بعد از گریه.","why":"وضعیت knee-to-chest و morphine؛ phenylephrine یا propranolol در مقاوم."}],"ch":"72","name":"Congenital heart disease: neonatal cyanosis, ductal-dependent shock and tet spells","name_fa":"بیماری قلبی مادرزادی: سیانوز نوزاد، شوک وابسته به داکتوس و حمله tet","cc":["pediatric-other","hypotension-shock"],"keywords":"congenital heart disease, cyanotic heart disease, ductal dependent, coarctation, transposition of great arteries, tetralogy of Fallot, tet spell, prostaglandin E1, hyperoxia test, سیانوز مادرزادی","status":"draft","features":["شش تظاهر شایع: سیانوز، شوک، CHF، سوفل پاتولوژیک، هیپرتانسیون و سنکوپ (جدول 72-1)؛ سیانوز و شوک معمولاً در 2 هفته اول و دراماتیک","نوزاد سیانوتیک: افتراق وسیع: سپسیس، پنومونی، متابولیک (فصل ۷۹) و NAT؛ hyperoxia test: با اکسیژن 100٪ در بیماری قلبی سیانوتیک PaO2/اشباع بالا نمی‌رود، در ریوی اغلب بهبود (ناقص)","سیانوز مرکزی (شامل مخاط) شاخص؛ سیانوز اندام دیستال ممکن است طبیعی باشد؛ در پوست تیره دشوار: اشباع پره‌داکتال (دست راست) و پست‌داکتال (پا) و فشار چهار اندام؛ سوفل همراه سیانوز: مطرح CHD ولی نبود سوفل رد نمی‌کند؛ تاکی‌پنه بدون زحمت و سطحی","شوک نوزاد (به‌ویژه 2 هفته اول): ductal-dependent: رنگ‌پریدگی/«خاکستری»، mottling، سیانوز، تغییر هوشیاری، تاکی‌کاردی و تاکی‌پنه؛ اختلاف نبض/فشار پره/پست‌داکتال (کوآرکتاسیون)","ارزیابی: CXR (اندازه/شکل قلب، جریان خون ریوی) و ECG (انحراف محور راست و RVH در سیانوتیک؛ LVH در انسداد خروجی چپ)؛ اکو تشخیص قطعی","TGA: شایع‌ترین سیانوتیک هفته اول؛ بدون کاردیومگالی یا سوفل؛ S2 بلند و منفرد؛ «egg on a string»؛ TOF: شایع‌ترین کلی؛ سوفل VSD و PS؛ سیانوز در شیرخوار/کودک؛ «boot-shaped»؛ squatting؛ tet spell: تنگی نفس حمله‌ای، سیانوز افزایش‌یافته و سنکوپ بعد از تغذیه/گریه/زور زدن","انسداد خروجی بطن چپ: بستن داکتوس → کاهش پرفیوژن، رنگ‌پریدگی، هیپوتانسیون، تاکی‌پنه و اسیدوز لاکتیک شدید؛ کاهش نبض پا نسبت به براکیال راست = کوآرکتاسیون"],"ddx":[{"n":"Sepsis in a neonate |","cm":1},{"n":"Ductal-dependent congenital heart disease |","cm":1},{"n":"Inborn error of metabolism |","cm":1},{"n":"Pneumonia / pulmonary disease |"},{"n":"Nonaccidental trauma |"}],"redflags":["شوک نوزاد، اختلاف نبض/فشار بین بازو و پا، سیانوز بی‌پاسخ به اکسیژن، tet spell با سنکوپ"],"guide":"سیانوز و دیسترس: اکسیژن با جریان بالا، مانیتور قلبی و اکسیژن و IV/IO پایدار. هشدار: نوزاد با اشباع پایین را تحمل می‌کند (HbF)؛ اکسیژن واژودیلاتور ریوی قوی است و می‌تواند «pulmonary steal» ایجاد کند و شوک سیستمیک را در lesion های وابسته به داکتوس مثل کوآرکتاسیون بدتر کند: پروستاگلاندین حیاتی است. شوک شدید با شک به shunt-dependent: PGE1 شروع با 0.05 µg/kg/min، کاهش به کمترین دوز مؤثر؛ تا 0.2 μg/kg/min اگر بهبود نیافت؛ عوارض: تب، فلاشینگ، اسهال، آپنه دوره‌ای. مشاوره فوری کاردیولوژی اطفال و در شوک اینتنسیویست اطفال. tet spell: وضعیت knee-to-chest و morphine sulfate 0.2 mg/kg SC/IM/IO؛ موارد مقاوم: phenylephrine برای هیپوتانسیون یا propranolol برای تاکی‌کاردی با مشاوره. علل غیرقلبی را درمان کن؛ چالش مایع 10 تا 20 mL/kg نرمال سالین و آنتی‌بیوتیک تجربی؛ در CHD نوزاد محتاطانه (بولوس 10 mL/kg). epinephrine داروی اولیه هیپوتانسیون: انفوزیون 0.05 تا 0.5 μg/kg/min. بستری در NICU/PICU.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 72: Pediatric Heart Disease, pp. 388–394"},"pediatric-chf-myocarditis":{"id":"pediatric-chf-myocarditis","variants":[{"id":"chf-peds-stable","o":{"I":[{"t":"Chest radiograph (cardiomegaly, cardiothoracic index > 0.6, lack of retrosternal air space); echocardiography"}],"L":[{"t":"Cardiac troponin T for suspected myocarditis (< 0.01 ng/mL reliably excludes myocarditis)"}],"T":[{"t":"Furosemide 1 to 2 mg/kg parenterally (increased work of breathing or CHF on radiograph)","fl":[{"k":"ci","v":"fluid restriction"}]},{"t":"Digoxin first digitalizing dose in the ED: 20 to 30 μg/kg in neonates and 30 to 50 μg/kg in infants and children 1 month to 2 years (milder CHF)"},{"t":"CPAP or BiPAP if needed"}],"Co":[{"t":"Pediatric cardiologist; definitive diagnosis often requires cardiac catheterization and surgical repair"}]},"name":"Pediatric congestive heart failure, compensated","level":"II","imp":"Pediatric congestive heart failure","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","o2":"O2 therapy: oxygen; child seated upright in a neutral thermal environment; nasal cannula or face mask with flow by age and weight","sc":"شیرخوار ۳ ماهه با خوردن ضعیف، تعریق، تاکی‌پنه بدون زحمت و کاردیومگالی.","why":"فوروزماید و اکسیژن؛ دیگوکسین در خفیف؛ اکو و کاردیولوژی."},{"id":"chf-peds-shock","o":{"I":[{"t":"Chest radiograph; ECG (diffuse ST changes, dysrhythmias, QRS > 120 ms); echocardiography urgently"}],"T":[{"t":"Dopamine 5 to 15 μg/kg/min, or Dobutamine 2.5 to 15 μg/kg/min (may cause significant tachycardia in infants)"},{"t":"Milrinone 50 μg/kg IV over 10 to 60 minutes followed by continuous infusion 0.25 to 0.75 μg/kg/min"},{"t":"Aggressive management of respiratory insufficiency, acute renal failure, lactic acidosis, DIC, hypoglycemia, hypocalcemia and fever"}],"Co":[{"t":"PICU; pediatric cardiologist"}]},"name":"Pediatric cardiogenic shock","level":"I","imp":"Pediatric cardiogenic shock","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"O2 therapy: oxygen; nasal cannula or face mask with flow by age and weight","sc":"کودک ۶ ماهه با نبض‌های دیستال غایب، پرفیوژن ضعیف و CHF.","why":"شوک کاردیوژنیک: انفوزیون inotrope به‌جای دیگوکسین."},{"id":"pericarditis-peds","o":{"I":[{"t":"Chest radiograph (cardiomegaly); echocardiogram urgently to distinguish pericardial effusion from dilated or hypertrophic cardiomyopathy and determine need for pericardiocentesis"}],"Co":[{"t":"Pediatric cardiologist"}]},"name":"Pediatric pericarditis / effusion","level":"II","imp":"Pediatric pericarditis with possible effusion","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"پسر ۱۰ ساله با درد پلورتیک و وضعیتی قفسه سینه، friction rub و کاردیومگالی.","why":"اکو فوری برای افیوژن و نیاز به پریکاردیوسنتز."}],"ch":"72","name":"Pediatric congestive heart failure, cardiogenic shock, myocarditis and pericarditis","name_fa":"نارسایی قلبی کودکان، شوک کاردیوژنیک، میوکاردیت و پریکاردیت","cc":["pediatric-respiratory","dyspnea","chest-pain"],"keywords":"pediatric heart failure, furosemide, digoxin, dopamine, dobutamine, milrinone, myocarditis, cardiomyopathy, pericarditis, troponin T, نارسایی قلبی اطفال","status":"draft","features":["CHF بعد از دوره نوزادی: مادرزادی ماه 2 تا 3 (VSD/ASD)، اکتسابی بعد از 3 ماه؛ زودرس: lesion های وابسته به داکتوس (کوآرکتاسیون، PDA)؛ تمایز از پنومونی دشوار و هر دو ممکن است همزمان","علائم: خوردن ضعیف، تعریق، تحریک‌پذیری یا بی‌حالی با تغذیه، گریه ضعیف؛ شدید: grunting، nasal flaring و دیسترس؛ تاکی‌پنه اولیه «بدون زحمت»، سپس کار تنفسی و رال","CXR: کاردیومگالی (به‌جز پریکاردیت کانستریکتیو)؛ شاخص کاردیوتوراسیک > 0.6؛ نبود فضای رتروسترنال","کاردیومیوپاتی: دیسترس تنفسی و مشکل تغذیه؛ S3/S4 پاتولوژیک؛ رال و ارگانومگالی","میوکاردیت: بعد از بیماری ویروسی؛ بیشتر در سن مدرسه؛ تنگی نفس، استفراغ، خوردن ضعیف، بی‌حالی، تب؛ پرفیوژن ضعیف؛ ECG: تغییرات ST منتشر، دیس‌ریتمی (QRS > 120 ms پیش‌آگهی بد)؛ تروپونین T حساس (< 0.01 ng/mL میوکاردیت را رد می‌کند)","پریکاردیت: درد پلورتیک و وضعیتی؛ صدای قلب خفه و friction rub؛ اکو فوری","CHF راست خالص: معمولاً ریوی (cor pulmonale)؛ ادم دور چشم اولین نشانه"],"ddx":[{"n":"Cardiogenic shock |","cm":1},{"n":"Cardiac tamponade (pericardial effusion) |","cm":1},{"n":"Myocarditis / dilated cardiomyopathy |","cm":1},{"n":"Pneumonia / bronchiolitis |"},{"n":"Congenital heart disease with decompensation (endocarditis) |"}],"redflags":["نبض دیستال از دست رفته، کاهش پرفیوژن، ECG با دیس‌ریتمی یا QRS پهن"],"guide":"نوزاد با تاکی‌پنه خفیف، هپاتومگالی و کاردیومگالی: نشسته و راحت، اکسیژن و محیط حرارتی خنثی. افزایش کار تنفسی یا CHF در CXR: furosemide 1 تا 2 mg/kg پارنترال. هیپوکسمی: اکسیژن، محدودیت مایع، دیورز، گاهی CPAP/BiPAP. دیگوکسین در CHF خفیف‌تر: دوز دیجیتالیزاسیون ED: 20 تا 30 μg/kg در نوزاد و 30 تا 50 μg/kg در 1 ماه تا 2 سال. شوک کاردیوژنیک: به‌جای دیگوکسین انفوزیون inotrope: dopamine 5 تا 15 μg/kg/min، dobutamine 2.5 تا 15 μg/kg/min (تاکی‌کاردی)، milrinone بار 50 μg/kg IV طی 10 تا 60 دقیقه سپس 0.25 تا 0.75 μg/kg/min. مدیریت تهاجمی عوارض ثانویه: نارسایی تنفسی، AKI، اسیدوز لاکتیک، DIC، هیپوگلیسمی، هیپوکلسمی و تب. درمان قطعی: کاتتریزاسیون و جراحی؛ PGE1 به‌عنوان موقت قبل از عمل.","section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 72: Pediatric Heart Disease, pp. 388–394"},"gastroenteritis-peds":{"id":"gastroenteritis-peds","variants":[{"id":"gastro-peds-mild-ors","o":{"L":[{"t":"Bedside glucose if altered mental status; clinical dehydration score (> 0 some dehydration; > 5 moderate-severe); serum electrolytes not routinely required; stool culture only if travel to high-risk country, high or persistent fever, > 10 stools in 24 hours or blood in the stool"}],"S":[{"t":"Oral rehydration solution (ORS) 45 to 60 mmol/L sodium: 50 to 100 mL/kg plus additional ORS for ongoing losses; aim about 30 mL (1 ounce) per kg per hour; small amounts frequently; nasogastric administration if oral challenge fails","fl":[{"k":"ci","v":"avoid tea, juice and sports drinks"}]}],"T":[{"t":"Ondansetron 0.15 mg/kg/dose orally (or 2 mg for 8 to < 15 kg; 4 mg for 15 to < 30 kg; 8 mg if ≥ 30 kg) for persistent vomiting","fl":[{"k":"ci","v":"avoid intravenous ondansetron (greater QT prolongation)"}]},{"t":"Continue normal diet including lactose-containing milk or formula; do not withhold feedings > 4 hours in a dehydrated child","fl":[{"k":"ci","v":"no loperamide or antimotility agents"}]}],"Co":[{"t":"Discharge if tolerating oral rehydration with adequate urine output; return if unable to tolerate oral fluids, bilious vomiting, less alert, or no longer wetting diapers"}]},"name":"Gastroenteritis with mild dehydration (oral rehydration)","level":"III","imp":"Acute gastroenteritis with mild dehydration","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"دختر ۲ ساله با ۵ بار اسهال و ۲ بار استفراغ از دیروز؛ تشنه، مخاط چسبناک و اشک کم.","why":"ORS کافی است؛ ondansetron خوراکی در استفراغ پایدار."},{"id":"gastro-peds-severe-dehydration","o":{"L":[{"t":"Serum electrolytes (severe dehydration or IV rehydration to be given; infants in the first 6 months), bedside glucose; blood tests for hemolysis, thrombocytopenia and acute kidney injury if E. coli O157:H7 outbreak"}],"S":[{"t":"Normal saline or Ringer's lactate 20-mL/kg bolus IV or IO every 20 minutes until perfusion improves and urine output is adequate","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]},{"t":"10% dextrose 5 mL/kg in infants or 25% dextrose 2 mL/kg in toddlers and older children","if":"hypoglycemia"}],"Co":[{"t":"Admit"}]},"name":"Gastroenteritis with severe dehydration / shock","level":"I","imp":"Acute gastroenteritis with severe dehydration","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"شیرخوار ۹ ماهه با اسهال و استفراغ ۳ روزه، خواب‌آلود، چشم گود، زبان خشک و بدون اشک.","why":"شدید یا تغییر هوشیاری: کریستالوئید وریدی/IO؛ قند و الکترولیت."},{"id":"gastro-peds-bacterial","o":{"L":[{"t":"Stool culture (blood in stool, > 10 stools in 24 hours, highly or persistently febrile, travel to high-risk country); E. coli O157:H7 outbreak: blood tests for hemolysis, thrombocytopenia and acute kidney injury"}],"A":[{"t":"Shigella (immunocompromised, severe disease, dysentery or systemic symptoms): azithromycin, ceftriaxone or ciprofloxacin; if susceptible ampicillin or trimethoprim-sulfamethoxazole"},{"t":"Nontyphoidal Salmonella (< 3 months, hemoglobinopathy, immunodeficiency, chronic GI disease, malignancy, severe colitis, bacteremia, sepsis): ampicillin, amoxicillin or trimethoprim-sulfamethoxazole; invasive disease: cefotaxime or ceftriaxone"},{"t":"Campylobacter (moderate-severe, relapse, immunocompromised, day care): erythromycin, azithromycin or ciprofloxacin","fl":[{"k":"note","v":"doses not given in the book; STEC: no antibiotics (possible increased risk of hemolytic-uremic syndrome)"}]}],"Co":[{"t":"Admit if toxic appearance, significant dehydration, altered mental status, or laboratory evidence of hemolytic anemia, thrombocytopenia, azotemia or significant sodium abnormality"}]},"name":"Bacterial gastroenteritis / dysentery","level":"II","imp":"Bacterial gastroenteritis / dysentery","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"پسر ۵ ساله با تب 39.5، اسهال خونی و ۱۲ دفع در ۲۴ ساعت.","why":"کشت مدفوع در تب بالا/خون؛ آنتی‌بیوتیک فقط در شدید یا گروه خطر؛ STEC آنتی‌بیوتیک ندارد."}],"ch":"73","name":"Vomiting, diarrhea and dehydration in infants and children (gastroenteritis)","name_fa":"استفراغ، اسهال و دهیدراتاسیون در شیرخواران و کودکان (گاستروانتریت)","cc":["pediatric-gi","diarrhea","nausea-vomiting"],"keywords":"pediatric gastroenteritis, dehydration, oral rehydration solution, ORS, ondansetron, clinical dehydration score, Shigella, Salmonella, E coli O157, hemolytic uremic syndrome, loperamide, اسهال کودکان","status":"draft","features":["گاستروانتریت تا 20٪ ویزیت‌های سرپایی حاد؛ بیشتر ویروسی و خودمحدود؛ از دست دادن آب و الکترولیت: دهیدراتاسیون، شوک هیپوولمیک یا اختلال الکترولیت","ارزیابی هیدراتاسیون سنگ‌بنای مدیریت (جدول 73-1: ظاهر عمومی، چشم، مخاط دهان/زبان، اشک؛ امتیاز > 0 = مقداری دهیدراتاسیون؛ > 5 = متوسط تا شدید)","مسیر مدفوعی-دهانی؛ ویروس‌ها جذب را مختل می‌کنند؛ باکتری‌ها با انتروتوکسین/سایتوتوکسین و تهاجم؛ dysentery: تهاجم ترمینال ایلئوم و کولون با خون، مخاط یا چرک","شیرخوار در خطر دهیدراتاسیون سریع و هیپوگلیسمی؛ همچنین بیماری مزمن، شرایط اجتماعی پرخطر یا سوءتغذیه","تشخیص بالینی: ≥ 3 مدفوع اسهالی در 24 ساعت ± استفراغ، درد شکم مبهم و تب؛ دهیدراتاسیون معمولاً ایزوتونیک: الکترولیت روتین نه مگر شدید یا قرار است مایع وریدی بدهیم؛ استثنا: شیرخوار 6 ماه اول (اختلال سدیم)","قند بالین در هر تغییر هوشیاری؛ کشت مدفوع: سفر به کشور پرخطر، تب بالا یا مداوم، > 10 مدفوع در 24 ساعت یا خون در مدفوع؛ شیوع E. coli O157:H7: کشت مدفوع و آزمایش همولیز، ترومبوسیتوپنی و AKI","افتراق: کولیت باکتریال، Hirschsprung، انسداد نسبی، IBD، HUS، آپاندیسیت (به‌ویژه پس از پرفوراسیون)؛ استفراغ ایزوله: اوتیت، UTI، سپسیس، malrotation، اینتوساسپشن، افزایش ICP، اسیدوز متابولیک، مسمومیت","استفراغ صفراوی/خونی، هماتوشزی یا درد شکم: علت غیر از گاستروانتریت ساده"],"ddx":[{"n":"Bilious vomiting (malrotation) / intussusception / appendicitis |","cm":1},{"n":"Hemolytic uremic syndrome |","cm":1},{"n":"Sepsis / meningitis |","cm":1},{"n":"Urinary tract infection / otitis media |"},{"n":"Bacterial colitis / Hirschsprung disease / inflammatory bowel disease |"},{"n":"Ingestion / metabolic acidosis |"}],"redflags":["استفراغ صفراوی یا خونی، هماتوشزی، تغییر هوشیاری، دهیدراتاسیون شدید یا شوک، ظاهر سمی"],"guide":"# دهیدراتاسیون\nبیشتر موارد فقط ORS: استفراغ منع نیست؛ مقدار کم و مکرر. ORS تجاری با سدیم 45 تا 60 mmol/L؛ چای، آب‌میوه، نوشابه ورزشی ناکافی (سدیم کم و قند زیاد). ORS 50 تا 100 mL/kg به‌علاوه جبران ادامه از دست دادن‌ها؛ هدف حدود 30 mL (1 oz) به‌ازای kg در ساعت؛ در شکست: لوله NG. دهیدراتاسیون شدید، ناپایداری همودینامیک یا تغییر هوشیاری که مانع مایع خوراکی است: کریستالوئید ایزوتونیک وریدی یا IO: نرمال سالین یا Ringer لاکتات بولوس 20 mL/kg هر 20 دقیقه تا بهبود پرفیوژن و ادرار کافی. هیپوگلیسمی: دکستروز 10٪ 5 mL/kg در شیرخوار یا دکستروز 25٪ 2 mL/kg در نوپا و بزرگ‌تر.\n# استفراغ\nondansetron 0.15 mg/kg/dose (یا 2 mg برای 8 تا < 15 kg؛ 4 mg برای 15 تا < 30 kg؛ 8 mg اگر ≥ 30 kg) ترجیحاً خوراکی کمک به ORS؛ ondansetron وریدی QT را بیشتر طولانی می‌کند: پرهیز. ترخیص: تحمل ORS، ادرار کافی و حداقل از دست دادن مداوم؛ رژیم طبیعی (شامل شیر لاکتوزدار) ادامه یابد.\n# اسهال\nخفیف بدون دهیدراتاسیون: تغذیه معمول؛ در دهیدراته تغذیه را > 4 ساعت متوقف نکن؛ رقیق کردن فرمولا لازم نیست (> 80٪ شیر کامل را تحمل می‌کنند). ضداسهال و ضدحرکت مثل loperamide توصیه نمی‌شود و در کودکان خردسال ممنوع. آنتی‌بیوتیک برای اکثریت غیرضروری و ممکن است خطر HUS را بیشتر کند؛ جدول 73-2: Shigella: خودمحدود؛ درمان در ایمنوساپرس، شدید، dysentery یا سیستمیک: azithromycin، ceftriaxone، ciprofloxacin (حساس: ampicillin یا TMP-SMX)؛ Salmonella غیرتیفوئیدی: درمان فقط < 3 ماه، هموگلوبینوپاتی، نقص ایمنی، بیماری مزمن GI، بدخیمی، کولیت شدید، باکتریمی، سپسیس: ampicillin، amoxicillin، TMP-SMX (مقاوم: azithromycin، فلوروکینولون؛ تهاجمی: cefotaxime، ceftriaxone)؛ Campylobacter: درمان در متوسط/شدید، عود، ایمنوساپرس، مهدکودک: erythromycin، azithromycin، ciprofloxacin؛ STEC: آنتی‌بیوتیک ندارد؛ Yersinia: خودمحدود؛ شدید: TMP-SMX، آمینوگلیکوزید، cefotaxime، فلوروکینولون، doxycycline؛ Vibrio cholerae: متوسط/شدید: azithromycin، doxycycline.\n# ترخیص و بستری\nبستری: ظاهر سمی، شرایط اجتماعی پرخطر، دهیدراتاسیون یا از دست دادن مداوم قابل‌توجه، تغییر هوشیاری، ناتوانی در نوشیدن، شواهد آزمایشگاهی همولیز/ترومبوسیتوپنی/ازوتمی/اختلال سدیم، شکم جراحی. بازگشت: عدم تحمل مایع خوراکی، استفراغ صفراوی، کاهش هوشیاری یا علائم دهیدراتاسیون (پوشک خشک). رژیم: کربوهیدرات پیچیده، گوشت بدون چربی، سبزی، میوه، ماست؛ پرهیز از چربی و قند ساده؛ رژیم BRAT توصیه نمی‌شود.","pearls":["استفراغ صفراوی = اورژانس جراحی تا خلاف آن ثابت شود (malrotation).","ondansetron خوراکی ترجیح دارد؛ فرم وریدی QT را بیشتر طولانی می‌کند."],"section":"pediatrics","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 73: Vomiting and Diarrhea in Infants and Children, pp. 395–399"}});
